-- DIBANGKITKAN OTOMATIS oleh scripts/build-curriculum.mjs dari docs/curriculum/. Jangan disunting tangan.
-- Kurikulum 8 level dipasang berdampingan dengan kurikulum pilot lama (Fase 1 docs/rencana-aplikasi.md).
-- Hanya dibaca aplikasi; tidak ada kebijakan tulis, isi berubah lewat dokumen lalu migrasi baru.

create table public.k8_cp(
  id integer primary key check (id = 1),
  text text not null check (length(trim(text)) > 0)
);
create table public.k8_levels(
  level integer primary key check (level between 1 and 8),
  title text not null check (length(trim(title)) > 0),
  description text not null check (length(trim(description)) > 0)
);
create table public.k8_indicators(
  level integer not null references public.k8_levels(level),
  number integer not null check (number between 1 and 14),
  slot text not null check (slot in ('A1', 'B1', 'E1', 'D1', 'C1', 'F1', 'A2', 'B2', 'E2', 'D2', 'C2', 'F2', 'EN', 'KR')),
  competency text not null check (length(trim(competency)) > 0),
  method text not null check (length(trim(method)) > 0),
  material text not null check (length(trim(material)) > 0),
  success text not null check (length(trim(success)) > 0),
  primary key (level, number),
  unique (level, slot)
);
create table public.k8_notes(
  doc text not null check (doc in ('A', 'B', 'C', 'D', 'E', 'F', 'EK', 'TEMA')),
  position integer not null check (position >= 1),
  title text not null,
  markdown text not null,
  primary key (doc, position)
);
create table public.k8_themes(
  number integer primary key check (number between 1 and 8),
  name text not null check (length(trim(name)) > 0),
  first_meeting integer not null check (first_meeting between 1 and 192),
  last_meeting integer not null check (last_meeting between 1 and 192),
  description text not null,
  objects text not null,
  vocabulary text not null,
  character text not null,
  illustration text not null,
  check (last_meeting >= first_meeting)
);
create table public.k8_subthemes(
  theme integer not null references public.k8_themes(number),
  position integer not null check (position between 1 and 4),
  name text not null check (length(trim(name)) > 0),
  first_meeting integer not null check (first_meeting between 1 and 192),
  last_meeting integer not null check (last_meeting between 1 and 192),
  primary key (theme, position),
  check (last_meeting >= first_meeting)
);
create table public.k8_theme_english(
  theme integer not null references public.k8_themes(number),
  kind text not null check (kind in ('noun', 'phrase')),
  position integer not null check (position >= 1),
  text text not null check (length(trim(text)) > 0),
  requestable boolean not null default false,
  primary key (theme, kind, position),
  check (kind = 'noun' or not requestable)
);
-- Kata benda English tidak berulang antartema (english-karakter.md).
create unique index k8_theme_english_noun_unique on public.k8_theme_english(lower(text)) where kind = 'noun';

do $$ declare t text; begin
  foreach t in array array['k8_cp','k8_levels','k8_indicators','k8_notes','k8_themes','k8_subthemes','k8_theme_english'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy %I on public.%I for select to authenticated using (is_member())', t || '_read', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

insert into public.k8_cp(id, text) values (1, 'Kurikulum 8 level Rumah Belajar Rainbow Kids Alfatih mendampingi anak dari kesiapan TK A sampai sasaran akhir kelas I melalui kemampuan menyimak, berbicara, mengenal bunyi dan huruf, membaca, menulis, bilangan, pola, ukuran, operasi hitung, English sederhana, dan pembiasaan karakter. Capaian akhir L8 dibangun di atas kemampuan L1–L7, sehingga anak tidak hanya mengerjakan tugas akhir, tetapi bertahap dari mengenali, menghubungkan, merangkai, menggunakan, memahami, mengolah, menjelaskan, sampai mulai mandiri. Kurikulum ini disusun dengan merujuk Capaian Pembelajaran Fase Fondasi dan awal Fase A dalam Keputusan Kepala BSKAP No. 046/H/KR/2025, dengan sasaran akhir setara kelas I; Level 8 tidak dianggap menyelesaikan seluruh Fase A.

Pada akhir L8, anak mampu memahami mini-narasi lisan dengan urutan kejadian dan sebab yang dinyatakan, lalu menceritakan cerita pendek berurutan yang memiliki penyelesaian jelas. Anak mampu membedakan grafem yang mirip sesuai bunyi yang didengar dan mengubah bunyi awal kata lisan untuk membentuk kata lain. Anak mampu membaca dua kalimat pendek yang memuat diftong dan memahami hubungan sebab-akibat sederhana dari bacaan itu. Anak mampu menyalin satu kalimat pendek dari papan serta menulis satu kalimat sederhana dari gagasannya sendiri. Anak mampu melanjutkan hitungan dua-dua sampai 20 dan memahami nilai digit pada bilangan 11–20. Anak mampu memperkirakan panjang benda dengan satuan tidak baku dan menyelesaikan pengurangan yang melewati 10 sampai bilangan awal 20 tanpa benda hitung yang disediakan. Dalam English, anak mampu memakai pola English levelnya dengan kosakata dari tema yang sudah dikenalkan. Dalam Karakter, anak mulai menjalankan rutinitas belajar pendek yang sudah dikenal secara mandiri.');

insert into public.k8_levels(level, title, description) values
  (1, 'Mulai Mengenali', 'Anak mulai merespons instruksi satu langkah, menyebut benda, mengenali vokal, mengikuti arah tulisan, membuat garis dasar, menghitung 1–5, menentukan banyak benda 1–3, dan mengelompokkan benda berdasarkan satu atribut. Level ini cocok untuk awal TK A atau anak yang masih membutuhkan tugas sangat konkret.'),
  (2, 'Menghubungkan Dasar', 'Anak mulai menghubungkan kalimat lisan sederhana, huruf awal nama, lambang bilangan 1–5, tulisan sebagai penanda benda, bentuk pramenulis, bentuk datar, dan jumlah benda sampai 5. Level ini masih berada di wilayah TK A dengan bahan nyata dan tugas pendek.'),
  (3, 'Merangkai Awal', 'Anak mulai mengikuti dua tindakan berurutan, membaca suku kata KV, mengenali lambang 6–10, menyalin dan menulis huruf, menghitung benda 6–10, serta melanjutkan pola AB. Level ini cocok untuk awal TK B atau anak yang sudah siap merangkai dua unsur.'),
  (4, 'Menghubungkan Kejadian', 'Anak memahami informasi dari dua kalimat yang didengar, membaca kata sederhana, menyalin dan menulis suku kata, menentukan bilangan sebelum/sesudah 0–10, membagi benda sampai 5 menjadi dua bagian, serta melanjutkan pola ABC. Level ini masih konkret, tetapi anak mulai menghubungkan bagian-bagian informasi.'),
  (5, 'Dasar Kelas I', 'Anak mulai membaca dan menulis kata yang lebih utuh, menceritakan pengalaman berurutan, mengenali bilangan 11–20, membagi benda sampai 10, membandingkan panjang, dan menyelesaikan penjumlahan dalam 10 pada bentuk simbolik. Level ini cocok untuk awal kelas I.'),
  (6, 'Memahami Struktur', 'Anak membaca kalimat pendek, menyalin frasa dan menulis kata dengan suku kata tertutup, memahami urutan waktu lisan, membandingkan bilangan 0–20, membentuk 10 dan satuan pada bilangan 11–20, mengurutkan panjang, dan menyelesaikan pengurangan dalam 10.'),
  (7, 'Mengolah Informasi', 'Anak mulai memahami sebab-akibat lisan, membaca dua kalimat dengan ng/ny, menulis kalimat dari dikte, menentukan posisi bilangan pada garis 0–20, melengkapi bentuk 10 + n, mengukur dengan satuan tidak baku, dan menjumlah melewati 10. Level ini menuju kelas I akhir.'),
  (8, 'Mandiri Awal', 'Anak membaca dan memahami dua kalimat pendek dengan diftong, menulis kalimat dari gagasan sendiri, memahami nilai digit 11–20, melanjutkan hitungan dua-dua sampai 20, memperkirakan panjang, dan menyelesaikan pengurangan melewati 10. Level ini adalah sasaran akhir kurikulum 8 level, setara akhir kelas I internal bimbel.');

insert into public.k8_indicators(level, number, slot, competency, method, material, success) values
  (1, 1, 'A1', 'Melakukan tindakan sesuai isi satu instruksi lisan.', 'Sampaikan empat instruksi satu per satu. Tunggu tindakan anak sebelum melanjutkan.', 'Buku kosong, sendok, gelas plastik, meja. Instruksi: **“Sentuh buku.” “Angkat sendok.” “Tunjuk gelas.” “Sentuh meja.”**', '**3 dari 4 instruksi** dilakukan dengan tindakan dan sasaran yang sesuai.'),
  (2, 1, 'A1', 'Menemukan satu informasi literal dari satu kalimat lisan sederhana.', 'Sampaikan setiap kalimat, kemudian pertanyaannya. Ada empat butir.', '**“Rina membawa buku.”** Siapa yang membawa buku? **“Adi memakai topi.”** Siapa yang memakai topi? **“Ibu minum susu.”** Apa yang diminum Ibu? **“Bola ada di meja.”** Di mana bolanya?', '**3 dari 4 jawaban** tepat. Kunci berurutan: **Rina; Adi; susu; di meja**.'),
  (3, 1, 'A1', 'Melakukan dua tindakan sesuai urutan yang disampaikan.', 'Sampaikan setiap pasangan instruksi sampai selesai sebelum anak bertindak. Guru menata ulang benda bila diperlukan.', 'Buku kosong, sendok, gelas plastik, meja. **“Sentuh buku, lalu angkat sendok.” “Sentuh gelas, lalu tunjuk buku.” “Angkat gelas, lalu sentuh meja.” “Tunjuk sendok, lalu sentuh buku.”**', '**3 dari 4 pasangan** memenuhi tindakan, sasaran, dan urutan. Satu pasangan mendapat satu poin. Kepatuhan tidak dinilai.'),
  (4, 1, 'A1', 'Menemukan informasi tersurat dari tuturan dua kalimat tentang satu kejadian.', 'Sampaikan kedua kalimat, kemudian satu pertanyaan. Ada empat butir.', '**“Rina membawa buku. Ia menaruhnya di meja.”** Di mana Rina menaruh buku? **“Budi memegang gelas. Siti meminjamnya untuk minum.”** Siapa yang meminjam gelas Budi? **“Siti membuka tas. Topi merah ada di dalamnya.”** Apa warna topi di dalam tas? **“Adi mencari bola. Ia menemukannya di bawah kursi.”** Di mana Adi menemukan bola?', '**3 dari 4 jawaban** tepat. Kunci: **di meja; Siti; merah; di bawah kursi**.'),
  (5, 1, 'A1', 'Menentukan informasi utama dari tuturan pendek yang juga memuat detail pendukung.', 'Sampaikan setiap tuturan, kemudian tanyakan **“Cerita tadi terutama tentang kegiatan apa?”**', '**“Kelas sedang dibersihkan. Beni mengelap meja.” “Ibu menambahkan garam. Ia sedang memasak sup.” “Keluarga bersiap pergi. Ayah memakai sepatu.” “Siti menyiram tanah. Ia sedang merawat tanaman.”**', '**3 dari 4 jawaban** menyebut kegiatan utama. Diterima: **bersih-bersih/membersihkan kelas; memasak/membuat sup; bersiap atau mau pergi; mengurus/merawat tanaman**. Belum mendapat poin bila hanya menyebut: **mengelap meja; menambahkan garam; memakai sepatu; menyiram tanah**. Jawaban yang memuat kegiatan utama sekaligus detail tetap diterima. Jawaban lain diterima bila merupakan padanan makna kegiatan utama; jawaban yang hanya merupakan padanan detail pendukung belum mendapat poin.'),
  (6, 1, 'A1', 'Menentukan urutan waktu dari tuturan yang memakai penanda urutan eksplisit.', 'Sampaikan empat tuturan, masing-masing diikuti satu pertanyaan.', '**“Pertama Siti mencuci tangan, lalu makan, kemudian minum.”** Apa yang dilakukan paling awal? **“Pertama Beni memakai sepatu, lalu berjalan, kemudian bermain.”** Apa yang dilakukan paling akhir? **“Sebelum makan, Rina mencuci tangan. Setelah makan, ia minum.”** Apa yang dilakukan paling awal? **“Dodi melepas sepatu setelah bermain. Sebelum bermain, ia memakai sepatu.”** Apa yang dilakukan paling akhir?', '**3 dari 4 jawaban** tepat. Kunci: **mencuci tangan; bermain; mencuci tangan; melepas sepatu**. Dengan ambang tersebut, anak harus menjawab tepat sedikitnya satu dari dua butir *sebelum/setelah*. Ini konsekuensi ambang keseluruhan, bukan tambahan syarat kelulusan terpisah.'),
  (7, 1, 'A1', 'Menentukan hubungan sebab–akibat yang dinyatakan eksplisit dalam tuturan.', 'Sampaikan setiap tuturan, kemudian tanyakan sebab dari akibat yang disebut.', '**“Siti haus, jadi ia minum.”** Mengapa Siti minum? **“Karena udara dingin, Beni memakai jaket.”** Mengapa Beni memakai jaket? **“Karena hujan, Rina membuka payung.”** Mengapa Rina membuka payung? **“Adi jatuh karena lantai licin.”** Mengapa Adi jatuh?', '**3 dari 4 jawaban** menyebut sebab yang tepat: **haus; udara dingin; hujan; lantai licin**. Menyebut akibat saja belum mendapat poin.'),
  (8, 1, 'A1', 'Menyebutkan urutan kejadian serta sebab yang dinyatakan dalam mini-narasi.', 'Setelah mini-narasi, tanyakan: **“Apa yang Nina lakukan sebelum menuang air?” “Setelah menuang air, apa yang Nina lakukan?” “Mengapa Nina mengambil gelas?” “Mengapa Nina meniup air?”**', '**“Karena haus, Nina mengambil gelas. Ia menuang air. Karena airnya panas, Nina meniupnya.”**', '**3 dari 4 jawaban** tepat. Periksa terpisah: **urutan** → mengambil gelas; meniup air. **Sebab** → haus; air panas. Harus terdapat sedikitnya satu jawaban tepat pada masing-masing komponen. A1 L8 merupakan integrasi urutan dan sebab yang disengaja.'),
  (1, 7, 'A2', 'Menyebut nama benda.', 'Tunjukkan empat benda satu per satu. Tanyakan **“Ini apa?”**', 'Buku kosong, bola polos, sendok, gelas plastik.', '**3 dari 4 benda** disebut dengan nama yang sesuai. Padanan nama yang lazim diterima.'),
  (2, 7, 'A2', 'Menyampaikan informasi konkret dalam satu kalimat.', 'Sediakan empat keadaan: anak memegang buku, memegang sendok, meletakkan bola di meja, dan meletakkan gelas di meja. Minta **“Ceritakan yang kamu lakukan dengan benda ini.”** Penataan dapat dibantu dengan isyarat.', 'Buku kosong, sendok, bola polos, gelas plastik, meja.', '**3 dari 4 tuturan** memuat satu klausa yang menyatakan tindakan/keadaan beserta benda yang dimaksud, sesuai kejadian. Sasaran panjang sekitar tiga kata; panjang bukan skor tersendiri. Nama benda saja belum mendapat poin.'),
  (3, 7, 'A2', 'Mendeskripsikan benda dalam satu kalimat.', 'Tunjukkan empat benda bergantian. Minta **“Benda ini seperti apa? Coba ceritakan.”** Anak boleh menyentuhnya.', 'Bola merah polos, kotak biru polos, sendok logam, kain lembut.', '**3 dari 4 tuturan** memuat klausa yang menyebut benda dan sedikitnya satu ciri fisik yang dapat diperiksa langsung. Sasaran panjang sekitar empat kata. Nama benda atau kata sifat yang berdiri sendiri belum mendapat poin.'),
  (4, 7, 'A2', 'Menyampaikan satu kejadian dalam dua kalimat yang saling berhubungan.', 'Guru mengambil buku lalu memasukkannya ke tas, tanpa menarasikan tindakan. Tanyakan **“Tadi Bu Guru melakukan apa? Coba ceritakan.”**', 'Buku kosong dan tas; satu peragaan dua tindakan.', 'Satu tuturan dengan **sedikitnya dua klausa berbeda**. Unsur wajib: **pengambilan buku; buku dimasukkan/berada di tas; kedua klausa merujuk kejadian yang sama**. Urutan penceritaan belum menjadi syarat tambahan.'),
  (5, 7, 'A2', 'Menceritakan pengalaman dengan urutan kejadian yang dapat ditelusuri.', 'Dengan isyarat atau contoh gerak tanpa narasi, ajak anak mengambil buku, memasukkannya ke tas, lalu meletakkan tas di meja. Setelah anak mengalaminya, minta **“Ceritakan yang kamu lakukan tadi dari awal sampai selesai.”**', 'Buku kosong, tas, meja. Tindakan anak tidak diberi skor.', 'Satu tuturan dengan **sedikitnya tiga klausa berbeda**. Unsur wajib: **mengambil buku; memasukkan buku ke tas; meletakkan tas di meja; urutan sesuai kejadian**.'),
  (6, 7, 'A2', 'Menceritakan kejadian berurutan memakai penanda waktu seperti *lalu/kemudian*.', 'Dengan isyarat atau contoh gerak tanpa narasi, ajak anak mengambil sendok, memasukkannya ke gelas, lalu meletakkan gelas di meja. Minta **“Ceritakan yang kamu lakukan tadi dari awal sampai selesai.”** Guru tidak menyebut penghubung waktu sasaran.', 'Sendok, gelas plastik kosong, meja. **Posisi awal: gelas berada di salah satu tangan anak; sendok berada di meja.** Guru membantu menyiapkan posisi sebelum rangkaian dimulai. Penyiapan gelas bukan unsur cerita yang wajib dinilai.', 'Unsur wajib: **mengambil sendok; memasukkan sendok ke gelas; meletakkan gelas di meja**, dalam sedikitnya **tiga klausa**; urutan sesuai; serta **sedikitnya satu penghubung waktu yang menghubungkan dua kejadian**. Diterima: **lalu, kemudian, terus, habis itu, setelah itu**. “Main terus” yang berarti terus-menerus tidak dihitung sebagai penghubung urutan.'),
  (7, 7, 'A2', 'Menceritakan kejadian berurutan yang menyertakan sebab sederhana dengan penghubung sebab seperti karena.', 'Guru menggeser pensil hingga jatuh; dengan isyarat, ajak anak mengambil dan mengembalikannya ke meja. Minta **“Ceritakan kejadian tadi dari awal, beserta alasannya.”** Guru tidak menyebut contoh penghubung sebab atau mencontohkan hubungan sebab.', 'Pensil dan meja. Anak melihat pensil terdorong/jatuh, kemudian mengambil dan mengembalikannya.', 'Unsur wajib: **pensil jatuh; pensil diambil; pensil dikembalikan; urutan sesuai**, dalam sedikitnya **tiga klausa**; serta **sedikitnya satu hubungan sebab yang sesuai kejadian**, menggunakan penghubung sebab seperti **karena, soalnya, gara-gara, atau sebab**. Sebab yang diterima: jatuh karena terdorong/tersenggol, atau diambil karena jatuh/berada di lantai. Kehadiran kata penghubung tanpa hubungan sebab yang sesuai belum memenuhi unsur.'),
  (8, 7, 'A2', 'Menceritakan cerita pendek berurutan yang mempunyai akhir/penyelesaian yang jelas.', 'Guru mencoba memasukkan bola ke kotak yang masih tertutup sehingga belum berhasil, membuka tutup, lalu memasukkan bola. Peragakan tanpa narasi. Minta **“Ceritakan apa yang terjadi dari awal sampai akhirnya.”**', 'Bola polos dan kotak bertutup yang mudah dibuka serta cukup besar untuk bola.', 'Satu cerita dengan **sedikitnya tiga klausa**, memuat **hambatan, tindakan mengatasi, dan hasil akhir**, dalam urutan sesuai kejadian. Semua unsur wajib diperiksa menggunakan rincian rubrik di bawah.'),
  (1, 2, 'B1', 'Mengenali lima grafem vokal.', 'Katakan, “Tunjuk tulisan untuk bunyi yang kamu dengar.” Ucapkan **/u/, /a/, /i/, /u/, /o/, /e/** satu per satu.', 'Deret **o a u e i**. Tidak ada grafem di luar cakupan L1.', '**5 dari 6** tepat. Kunci: **u, a, i, u, o, e**.'),
  (2, 2, 'B1', 'Mengenali grafem m, n, b, p.', 'Dengan perintah yang sama, ucapkan **/n/, /b/, /p/, /n/, /m/, /b/**. Bukan nama huruf.', 'Deret **p m a b n**; `a` pengecoh dari L1.', '**5 dari 6** tepat. Kunci: **n, b, p, n, m, b**.'),
  (3, 2, 'B1', 'Mengenali grafem s, t, l, k, d.', 'Ucapkan **/l/, /s/, /d/, /s/, /t/, /k/** satu per satu.', 'Deret **k d s m l t**; `m` pengecoh dari L2.', '**5 dari 6** tepat. Kunci: **l, s, d, s, t, k**.'),
  (4, 2, 'B1', 'Mengenali grafem g, r, h, j, c.', 'Ucapkan **/r/, /g/, /h/, /c/, /g/, /j/**. Gunakan ketentuan pelafalan, termasuk toleransi `/c/` dan `/h/`; jangan menyebut nama huruf.', 'Deret **j h c g n r**; `n` pengecoh dari L2.', '**5 dari 6** tepat. Kunci: **r, g, h, c, g, j**.'),
  (5, 2, 'B1', 'Mengenali grafem w, y, f, z, v, q, x.', 'Katakan, “Tunjuk huruf yang namanya saya sebut.” Ucapkan **ye, ef, eks, we, ef, fe, ki, zet**. “Fe” adalah pelafalan nama `v`.', 'Deret **x f w q v y z**. Semua tujuh grafem ditanyakan; `f` diulang.', '**7 dari 8** tepat. Kunci: **y, f, x, w, f, v, q, z**. Hasil menunjukkan pengenalan identitas huruf, bukan penguasaan seluruh korespondensi bunyinya.'),
  (6, 2, 'B1', 'Mengenali ng dan ny sebagai grafem yang mewakili bunyi tertentu.', 'Katakan, “Dengarkan. Tunjuk tulisan untuk bunyi paling awalnya.” Ucapkan **nga, nya, nya, nga, nya, nga**. Anak hanya menunjuk, tidak diminta memisahkan atau menghasilkan bunyi.', 'Deret **n ny g ng y**. *Nga/nya* tidak ditulis. Yang dipetakan ialah bunyi awal /ng/ atau /ny/, bukan seluruh suku kata.', '**5 dari 6** tepat. Kunci: **ng, ny, ny, ng, ny, ng**. Menunjuk satu huruf penyusun saja tidak mendapat poin.'),
  (7, 2, 'B1', 'Mengenali diftong ai, au, oi dalam kata.', 'Katakan, “Dengarkan katanya. Tunjuk tulisan untuk bunyi gabungan yang kamu dengar.” Ucapkan kata secara wajar dengan diftong jelas, tanpa mengeja atau mengisolasi diftong sebagai petunjuk.', 'Pilihan **oi ai au**. Urutan kata lisan: **pantai; pulau; koboi; sampai; konvoi; kerbau**. Kata tidak ditulis dan maknanya tidak ditanyakan.', '**5 dari 6** tepat. Kunci: **ai, au, oi, ai, oi, au**. Dua butir per diftong memastikan sedikitnya satu respons benar untuk setiap diftong pada hasil Lulus.'),
  (8, 2, 'B1', 'Menunjuk grafem b, d, atau p sesuai bunyi yang diucapkan guru di antara pilihan grafem yang bentuknya mirip.', 'Katakan, “Tunjuk tulisan untuk bunyi yang kamu dengar.” Ucapkan **/b/, /p/, /d/, /p/, /b/, /d/**. Tidak memberikan model grafem untuk dicocokkan.', 'Deret huruf kecil **p b q d**, tetap terlihat. `q` hanya pengecoh, tidak menjadi sasaran bunyi.', '**5 dari 6** tepat. Kunci: **b, p, d, p, b, d**. Hasil tidak membuktikan penguasaan bunyi `q`.'),
  (1, 8, 'B2', 'Menirukan urutan dua bunyi vokal yang didengar.', 'Katakan, “Dengarkan dua bunyi, lalu tirukan keduanya.” Contoh tidak dinilai: guru mengucapkan **/o/ … /a/** lalu mencontohkan pengulangannya. Setelah itu, berikan empat pasangan penilaian.', '**/a/ … /i/**; **/u/ … /o/**; **/e/ … /a/**; **/i/ … /u/**. Dua vokal terpisah, bukan satu diftong.', '**3 dari 4** pasangan ditirukan dengan kedua bunyi dan urutan tepat. Kunci sesuai pasangan. Satu bunyi saja atau urutan terbalik tidak memenuhi.'),
  (2, 8, 'B2', 'Menyebut bunyi awal dari kata yang didengar.', 'Contoh: “*Sapu*. Bunyi paling awalnya /s/.” Ucapkan setiap kata utuh, lalu tanyakan, “Bunyi paling awalnya apa?” Jangan memperpanjang konsonan awal.', '**meja, nasi, baju, paku**. Semua dua suku kata terbuka tanpa gugus konsonan awal.', '**3 dari 4** tepat. Kunci: **/m/, /n/, /b/, /p/**. Nama huruf, suku kata awal, atau kata utuh tidak memenuhi.'),
  (3, 8, 'B2', 'Menggabungkan dua suku kata lisan menjadi satu kata.', 'Contoh: “*Ku* … *da*, disatukan menjadi *kuda*.” Pada penilaian, ucapkan pasangan lalu tanyakan, “Kalau disatukan, bunyinya apa?” Jangan menyebut hasilnya.', '**pi … ta; to … pi; ban … tal; lam … pu**. Dua kata **KV-KV**, satu **KVK-KVK**, dan satu **KVK-KV**. Semua tetap dua suku kata.', '**3 dari 4** tepat. Kunci: **pita; topi; bantal; lampu**. Seluruh bagian, termasuk konsonan penutup, harus dipertahankan dalam kata hasil gabungan. Bagian terakhir saja atau pengulangan terpisah seperti stimulus tidak memenuhi.'),
  (4, 8, 'B2', 'Memisahkan satu kata lisan menjadi suku kata penyusunnya.', 'Contoh: “*Kota*, bagian katanya *ko* … *ta*.” Ucapkan kata utuh, lalu minta, “Ucapkan bagian katanya satu-satu.” Tidak memberi tepukan atau jeda penanda batas.', '**saku; kelapa; seragam; sembilan**. Struktur berurutan: **KV-KV; KV-KV-KV; KV-KV-KVK; KVK-KV-KVK**. *Sembilan* hanya bahan bunyi, bukan tugas bilangan.', '**3 dari 4** tepat. Kunci: **sa-ku; ke-la-pa; se-ra-gam; sem-bi-lan**. Semua suku kata, termasuk konsonan penutup, disebut pada batas yang tepat dan tetap berurutan.'),
  (5, 8, 'B2', 'Menghilangkan satu suku kata dari kata yang didengar.', 'Contoh: “*Meja*, tanpa bagian bunyi *me*, menjadi *ja*.” Pada penilaian: “Ucapkan [kata] tanpa bagian bunyi [sasaran].” Sebut kata utuh sebelum sasaran penghilangan.', '**roti tanpa ti; boneka tanpa bo; telepon tanpa te; jembatan tanpa tan**. Struktur kata sama dengan komposisi L4: **KV-KV; KV-KV-KV; KV-KV-KVK; KVK-KV-KVK**. Posisi penghilangan: **akhir, awal, awal, akhir**.', '**3 dari 4** tepat. Kunci: **ro; neka; lepon; jemba**. Semua sisa bunyi dipertahankan dalam urutan semula; kualitas vokal mengikuti stimulus. Hasil tidak harus kata bermakna. Selalu menghapus awal atau selalu akhir hanya menghasilkan dua jawaban tepat.'),
  (6, 8, 'B2', 'Menggabungkan dua fonem menjadi satu suku kata KV.', 'Contoh: “/l/ … /a/, disatukan menjadi *la*.” Minta, “Satukan dua bunyi ini,” lalu ucapkan pasangan fonem. Jangan memakai nama huruf atau pembawa bunyi *nga/nya*.', '**/m/ … /a/; /b/ … /i/; /s/ … /u/; /t/ … /o/**. Semua **K+V**; dua konsonan yang dapat dipanjangkan dan dua konsonan letup, dengan empat vokal berbeda.', '**3 dari 4** tepat. Kunci: **ma; bi; su; to**, masing-masing satu suku kata. Fonem yang tetap terpisah, vokal terakhir saja, atau hasil dengan vokal tambahan tidak memenuhi.'),
  (7, 8, 'B2', 'Memisahkan satu suku kata KV menjadi fonem penyusunnya.', 'Contoh: “*Lu*, bunyi-bunyi kecilnya /l/ … /u/.” Ucapkan suku kata utuh, lalu minta, “Ucapkan bunyi-bunyi kecilnya satu-satu.” Jangan memisahkan stimulus melalui jeda.', '**mi; bu; so; ta**. Semua **KV**, memakai konsonan **m, b, s, t** serta vokal **i, u, o, a**. Komposisi sama dengan L6, pasangan berbeda.', '**3 dari 4** tepat. Kunci: **/m/–/i/; /b/–/u/; /s/–/o/; /t/–/a/**. Kedua fonem harus terpisah dan berurutan. Nama huruf atau suku kata utuh tidak memenuhi.'),
  (8, 8, 'B2', 'Mengganti satu fonem pada kata lisan untuk membentuk kata lain.', 'Contoh: “Pada *palu*, ganti bunyi paling awal /p/ dengan /m/, menjadi *malu*.” Pada penilaian: “Pada [kata], ganti bunyi paling awal [lama] dengan [baru]. Jadi apa?” Jangan menyebut suku kata atau kata hasilnya.', '**batu: /b/ menjadi /s/; mata: /m/ menjadi /b/; pita: /p/ menjadi /k/; saku: /s/ menjadi /p/**. Kata awal dan hasil **KV-KV**; satu fonem awal berubah.', '**3 dari 4** tepat. Kunci: **satu; bata; kita; paku**. Anak menyebut seluruh kata baru dengan bunyi lainnya tetap. Bunyi pengganti saja, suku kata awal saja, atau perubahan bunyi lain tidak memenuhi.'),
  (1, 5, 'C1', 'Mengikuti arah membaca pada satu baris tulisan dari titik awal yang benar.', 'Tampilkan empat baris secara terpisah pada posisi berbeda. Tanyakan, **“Kalau tulisan ini dibaca, mulai di mana? Tunjukkan jalannya sampai selesai.”** Tidak memberi isyarat kiri/kanan atau meminta nama huruf.', '**a i u; e a o; u e i; o i a**.', '**3 dari 4**: mulai pada huruf paling kiri, bergerak ke kanan, berakhir pada huruf terakhir. Ketelitian gerak jari bukan skor tersendiri.'),
  (2, 5, 'C1', 'Membedakan tulisan atau huruf dari angka dan gambar.', 'Pada setiap susunan, minta **“Tunjuk yang berupa tulisan huruf.”** Tidak meminta membaca atau menamai pembanding.', 'Susunan kiri→kanan: **aoi / 314 / segitiga; persegi / uie / 527; 682 / segitiga / oau; persegi / ioa / 935**. Kata *segitiga/persegi* dalam dokumen diganti goresan bentuknya, bukan ditulis sebagai kata.', '**3 dari 4**. Kunci **aoi, uie, oau, ioa**, posisi **1, 2, 3, 2**.'),
  (3, 5, 'C1', 'Membaca suku kata terbuka berpola KV.', 'Tampilkan empat suku kata satu per satu untuk dibaca tanpa bantuan bunyi.', '**ma; ni; bu; po**.', '**3 dari 4** dibaca tepat, dengan kedua bunyi menyatu menjadi KV.'),
  (4, 5, 'C1', 'Membaca kata sederhana berpola KV-KV atau V-KV.', 'Tampilkan empat kata satu per satu untuk dibaca sendiri.', '**paku; dasi; ibu; itu**. Dua KV-KV dan dua V-KV.', '**3 dari 4** tepat sesuai tulisan. Ambang mengharuskan sedikitnya satu kata tepat dari setiap struktur.'),
  (5, 5, 'C1', 'Membaca kata yang memuat suku kata tertutup sederhana.', 'Tampilkan empat kata satu per satu.', '**tas; kapas; lampu; bantal**: KVK; KV-KVK; KVK-KV; KVK-KVK.', '**3 dari 4** tepat sesuai tulisan, termasuk konsonan penutup.'),
  (6, 5, 'C1', 'Membaca satu kalimat pendek dengan struktur kata yang telah dikuasai.', 'Tampilkan satu kalimat; minta anak membaca seluruhnya.', '**“Rina makan nasi putih.”** Empat kata.', 'Sedikitnya **3 dari 4 kata** tepat dan jumlah kesalahan kata paling banyak satu. Kunci sesuai kalimat.'),
  (7, 5, 'C1', 'Membaca dua kalimat pendek yang memuat kata dengan ng/ny.', 'Tampilkan dua kalimat; minta anak membaca keduanya.', '**“Nyamuk hinggap dekat bunga. Nyala lilin itu terang.”** Delapan kata; `ny`: nyamuk, nyala; `ng`: hinggap, bunga, terang.', 'Sedikitnya **7 dari 8 kata** tepat dan jumlah kesalahan paling banyak satu. Dengan ambang ini, terdapat pembacaan tepat pada kata dengan `ng` maupun `ny`.'),
  (8, 5, 'C1', 'Membaca dua kalimat pendek yang memuat kata dengan diftong ai/au/oi.', 'Tampilkan dua kalimat; minta anak membaca keduanya.', '**“Koboi sampai di pantai. Pulau hijau tampak sepi.”** Delapan kata.', 'Sedikitnya **7 dari 8 kata** tepat, kesalahan paling banyak satu, dan sedikitnya satu kata tepat untuk setiap diftong: `ai` → **sampai/pantai**; `au` → **pulau/hijau**; `oi` → **koboi**. Karena hanya satu kata `oi`, **koboi wajib tepat**.'),
  (1, 11, 'C2', 'Menunjukkan tulisan yang mewakili identitas dirinya atau orang yang dikenal.', 'Tetapkan satu nama sasaran dan satu susunan sebelum tes. Tanyakan **“Mana tulisan namamu?”** Untuk orang dikenal, sesuaikan pertanyaan dengan orang sasaran. Tidak membacakan pilihan atau memperlihatkan model nama.', '**Enam nama:** sasaran; dua pengecoh berhuruf awal sama; tiga pengecoh berhuruf awal berbeda dari sasaran dan satu sama lain. Panjang seluruh pengecoh berselisih maksimal satu huruf dari sasaran. Contoh untuk **Rani**, susunan dua baris: **Dita / Rudi / Rani**, kemudian **Bima / Romi / Sela**.', '**Lulus bila nama sasaran ditunjuk tepat** pada satu keputusan akhir tanpa petunjuk atau koreksi guru. Contoh: **Rani, posisi 3**, dihitung dari kiri ke kanan pada baris atas, lalu bawah. Tidak ada pengulangan sasaran sebagai butir tambahan.'),
  (2, 11, 'C2', 'Menghubungkan tulisan penanda benda dengan referennya setelah makna tulisan diperkenalkan pada kesempatan uji yang sama.', 'Ikuti Prosedur C2 L2. Perkenalkan ketiga pasangan tulisan–benda bersama dengan durasi setara; urutan penamaan **lap, air, roti**. Tutup tulisan, ubah posisi benda di balik penghalang, kemudian tampilkan label satu per satu pada tempat netral tanpa membacakannya. Contoh urutan hasil pengacakan prauji: **air, roti, lap**. Kelima benda tetap tersedia.', 'Tulisan **lap, air, roti**; kain lap polos yang dibentangkan, air dalam wadah bening polos, dan roti tanpa kemasan. Pengecoh **sendok dan topi**, keduanya tanpa tulisan. Papan, alat tulis, dan penghalang polos.', '**3 dari 3** referen ditunjuk tepat. Kunci untuk contoh urutan: **air dalam wadah; roti; kain lap**. Jika urutan prauji berbeda, kunci mengikuti label yang ditampilkan. Membaca nyaring tidak diwajibkan.'),
  (3, 11, 'C2', 'Mengenali makna kata benda KV-KV dari kosakata inti tetap kurikulum.', 'Tampilkan enam kata satu per satu. Minta menunjuk referen, tanpa guru membaca kata dan tanpa mewajibkan anak membaca nyaring.', '**buku; bola; susu; mata; kaki; sapi**. Referen: buku kosong, bola polos, susu dalam wadah bening, mata dan kaki diri/guru, **mainan sapi**. Pengecoh: sendok dan **mainan kucing**.', '**5 dari 6** hubungan tepat sesuai kata. Menunjuk mata tidak perlu menyentuhnya. Kata tidak diajarkan sebelum diagnostik; pengenalan utuh maupun pembacaan diterima. Kegagalan tidak langsung berarti anak tidak memahami makna tulisan.'),
  (4, 11, 'C2', 'Mencocokkan kata baru yang dibaca sendiri dengan referen konkret yang sesuai.', '**Tahap 1:** seluruh referen disembunyikan; anak membaca empat kata, guru mencatat ketepatan tanpa koreksi. **Tahap 2:** buka referen; tunjuk kata satu per satu tanpa membacanya, anak memilih benda yang dimaksud. Tulisan tetap terlihat.', '**pita; topi; palu; ubi**: tiga KV-KV dan satu V-KV. Benda terkait; pengecoh gelas dan sendok. “Baru” berarti paket tidak dimodelkan atau dilatih sebelum tes, bukan klaim anak belum pernah menjumpai kata tersebut.', '**3 dari 4** butir memenuhi pembacaan tepat sebelum referen dibuka **dan** pencocokan tepat. Kunci sesuai keempat kata. Koreksi diri setelah referen terlihat tidak memperbaiki skor membaca.'),
  (5, 11, 'C2', 'Mengelompokkan kata tertulis berdasarkan kategori makna sederhana.', 'Jelaskan kategori secara lisan: **alat untuk makan/minum** atau **bahan makanan/memasak**, tanpa contoh kata penilaian. Anak membaca setiap kata lalu menyebut kategorinya. Tanpa benda atau label kategori tertulis.', '**garpu; gula; beras; gelas; sendok; garam**.', '**5 dari 6** dibaca tepat dan dikategorikan tepat. Kunci **alat; bahan; bahan; alat; alat; bahan**. Jawaban singkat *alat/bahan* diterima.'),
  (6, 11, 'C2', 'Menemukan satu informasi literal dari kalimat pendek yang dibaca sendiri.', 'Setelah anak membaca, tanyakan: **“Apa warna barang itu?” “Siapa yang diceritakan?” “Apa yang dilakukan?” “Barang apa yang disebut?”**', '**“Doni beli topi merah.”** Tidak menyediakan topi merah atau konteks pemberi jawaban.', '**3 dari 4** tepat: **merah; Doni; beli/membeli; topi**. Tidak ditambahkan ambang membaca C1 sebagai syarat kedua.'),
  (7, 11, 'C2', 'Menentukan urutan kejadian dari dua kalimat pendek yang dibaca sendiri.', 'Setelah anak membaca, tanyakan: **“Apa yang terjadi paling akhir?” “Apa yang terjadi paling awal?” “Sesudah kejadian pertama, apa yang terjadi?” “Sebelum kejadian terakhir, apa yang terjadi?”**', '**“Siti duduk lalu lompat. Siti minum lalu lari.”** Delapan kata. Tidak diperagakan.', '**3 dari 4** tepat: **lari; duduk; lompat; minum**. Urutan mengacu pada teks.'),
  (8, 11, 'C2', 'Menentukan hubungan sebab–akibat sederhana dari dua kalimat pendek yang dibaca sendiri.', 'Setelah dibaca, tunjuk seluruh kalimat pertama: **“Apa yang terjadi pada tokohnya?” “Apa penyebabnya?”** Pada kalimat kedua: **“Apa penyebab kejadian di sini?” “Apa akibatnya pada tokoh?”** Tidak menunjuk potongan jawaban.', '**“Sebab hujan, Danu senang. Rika kesal sebab panas.”** Delapan kata; posisi sebab berbeda antarkalimat.', '**3 dari 4** tepat: **Danu senang; hujan; panas; Rika kesal/jengkel**. Nama boleh tidak diulang karena kalimat telah ditentukan. Jawaban harus terkait kalimat yang ditanyakan; daftar kata tanpa hubungan tersebut tidak mendapat poin.'),
  (1, 4, 'D1', 'Meniru garis dasar dari model visual.', 'Tampilkan empat model satu per satu. Katakan, “Buat seperti ini di tempat kosong.” Model yang sedang ditiru tetap terlihat.', 'Garis tegak; mendatar; miring naik ke kanan; lengkung terbuka ke kanan.', '**3 dari 4** sesuai jenis dan orientasi model menurut rubrik pramenulis. Kunci mengikuti empat model; arah gerak pensil bebas.'),
  (2, 4, 'D1', 'Meniru bentuk pramenulis sederhana dari model visual.', 'Tampilkan empat bentuk satu per satu dengan perintah yang sama; tidak meminta nama bentuk.', 'Silang tegak–mendatar; lingkaran; siku dua garis; segi empat tertutup.', '**3 dari 4** memenuhi ciri bentuk dan toleransi pertemuan/penutupan. Kunci: empat lengan berpotongan; putaran tanpa sudut; dua garis bertemu membentuk siku; empat sisi dan sudut.'),
  (3, 4, 'D1', 'Menyalin satu huruf dari model visual.', 'Tampilkan satu huruf setiap butir; minta menyalin di ruang kosong.', '**m; b; s; k**, huruf kecil.', '**3 dari 4** dikenali sebagai huruf sasaran, dengan orientasi dan kapital/kecil sesuai model. Kunci **m; b; s; k**.'),
  (4, 4, 'D1', 'Menyalin satu suku kata KV dari model visual.', 'Tampilkan dan salin satu KV setiap butir, tanpa kotak per huruf.', '**na; si; ku; bo**.', '**3 dari 4 KV** tepat kedua huruf dan urutannya. Kunci **na; si; ku; bo**; satu huruf tepat saja belum memenuhi butir.'),
  (5, 4, 'D1', 'Menyalin satu kata sederhana sekitar dua suku kata.', 'Salin dua kata secara bergantian, masing-masing pada ruang jawaban terpisah; model terkait tetap terlihat.', '**paku; meja**, masing-masing empat huruf, KV-KV.', '**Paling banyak satu kesalahan huruf** pada delapan huruf keseluruhan, sehingga sedikitnya satu kata tepat seluruhnya. Kunci **paku; meja**.'),
  (6, 4, 'D1', 'Menyalin frasa dua kata dengan mempertahankan pemisahan antarkata.', 'Salin satu frasa; model utuh tetap terlihat.', '**topi baru**, dua kata, delapan huruf.', '**Paling banyak satu kesalahan huruf**, serta satu batas kata memenuhi rubrik spasi tanpa pemisahan palsu di dalam kata. Kunci **topi / baru**.'),
  (7, 4, 'D1', 'Menyalin satu kalimat pendek dari model visual yang berada dekat.', 'Salin kalimat dari model dekat, sekitar 30–40 cm dari mata, tetap terlihat.', '**“Beni buka laci.”** Tiga kata, 12 huruf; tinggi huruf model sekitar 8 mm.', '**Paling banyak satu kesalahan gabungan huruf/kapital/titik**, serta dua batas kata memenuhi rubrik spasi. Kunci **Beni / buka / laci**.'),
  (8, 4, 'D1', 'Menyalin satu kalimat pendek dari model visual yang berjarak (papan).', 'Salin dari papan sekitar 1,5–2 m, tanpa salinan dekat; model tetap terlihat.', '**“Rina cuci kaki.”** Tiga kata, 12 huruf; tinggi huruf sekitar 3–4 cm dan dapat dilihat jelas.', 'Sama dengan L7: **paling banyak satu kesalahan gabungan huruf/kapital/titik**, serta dua batas kata tepat. Kunci **Rina / cuci / kaki**. Kenaikan berasal dari jarak model, bukan panjang.'),
  (1, 10, 'D2', 'Membuat garis atau bentuk dasar yang disebut secara lisan tanpa melihat model.', 'Sampaikan bergantian: “Buat satu garis tegak”; “Buat satu garis mendatar”; “Buat satu garis miring”; “Buat satu lingkaran.” Tanpa gerakan contoh.', 'Kertas polos; empat instruksi lisan.', '**3 dari 4** sesuai kategori pramenulis. Kunci tegak; mendatar; miring; lingkaran. Miring boleh ke kedua arah; lingkaran boleh oval.'),
  (2, 10, 'D2', 'Menulis huruf pertama namanya dari ingatan.', 'Tetapkan nama panggilan sebenarnya sebelum tes. Minta, “Tuliskan huruf paling depan dari namamu.” Guru tidak menyebut huruf jawabannya.', 'Nama panggilan anak yang sudah ditetapkan; tanpa tulisan nama.', 'Huruf pertama tepat dan dikenali, kapital/kecil diterima. Contoh guru: Rani → **R/r**. Jika anak menulis seluruh nama, hanya huruf pertama dinilai.'),
  (3, 10, 'D2', 'Menulis satu huruf berdasarkan bunyi yang disebutkan.', 'Katakan, “Tulis huruf untuk bunyi yang kamu dengar.” Ucapkan satu fonem setiap butir.', '**/a/; /m/; /s/; /b/**, mengikuti kalibrasi pelafalan Alur B.', '**3 dari 4** tepat. Kunci **a; m; s; b**, kapital setara diterima. Tambahan huruf dalam satu jawaban membuat butir itu tidak tepat.'),
  (4, 10, 'D2', 'Menulis satu suku kata KV dari dikte.', 'Diktekan setiap KV secara utuh, satu per satu; tanpa pemisahan fonem.', '**mu; ta; bi; so**.', '**3 dari 4** tepat kedua huruf dan urutannya. Kunci **mu; ta; bi; so**.'),
  (5, 10, 'D2', 'Menulis satu kata KV-KV dari dikte.', 'Diktekan dua kata bergantian; sediakan ruang jawaban terpisah.', '**baju; nasi**, masing-masing empat huruf, KV-KV.', '**Paling banyak satu kesalahan huruf** pada delapan huruf keseluruhan, sehingga sedikitnya satu kata tepat seluruhnya. Kunci **baju; nasi**.'),
  (6, 10, 'D2', 'Menulis satu kata yang memuat suku kata tertutup dari dikte.', 'Diktekan dua kata secara utuh, satu per satu; jangan menekankan konsonan penutup.', '**kapas; sabun**, masing-masing lima huruf, KV-KVK.', '**Paling banyak satu kesalahan huruf** pada sepuluh huruf keseluruhan. Kunci **kapas; sabun**. Menghilangkan konsonan akhir kedua kata berarti dua kesalahan dan belum memenuhi.'),
  (7, 10, 'D2', 'Menulis satu kalimat pendek dari dikte.', 'Diktekan seluruh kalimat sebelum anak menulis. Boleh satu pengulangan utuh atas permintaan; tanpa pengulangan per kata atau petunjuk spasi/titik.', '**“Dina minum teh.”** Tiga kata, 12 huruf; struktur KV-KV, KV-KVK, KVK.', '**Paling banyak satu kesalahan huruf** keseluruhan, serta dua batas kata memenuhi rubrik spasi. Kunci **Dina / minum / teh**. Kapital awal dan titik tidak menentukan lulus.'),
  (8, 10, 'D2', 'Menulis satu kalimat sederhana berdasarkan gagasan sendiri.', 'Minta anak menyatakan satu gagasan tentang dirinya atau benda sekitar, lalu menuliskannya. Guru tidak merumuskan kalimat, mendiktekan kembali, atau menyediakan kata tambahan. Anak boleh mengubah gagasannya sendiri sebelum selesai.', 'Kertas tanpa model; kosakata pilihan anak dalam cakupan inventaris. Tidak ada kalimat jawaban baku.', 'Satu kalimat gagasan sendiri memenuhi seluruh syarat minimum rubrik D2 L8: **minimal tiga kata; subjek dan predikat tertulis; batas kata tepat; maksimal satu kesalahan huruf per kata; tidak ada suku kata hilang**. Seluruh kalimat dinilai meskipun lebih dari empat kata.'),
  (1, 3, 'E1', 'Mengucapkan urutan bilangan 1–5.', 'Katakan, “Sebutkan urutan bilangan mulai satu sampai lima.” Anak mengucapkan satu rangkaian sendiri, tanpa hitung bersama atau lagu contoh.', 'Instruksi lisan; tanpa kumpulan benda atau deret angka.', 'Satu rangkaian **1, 2, 3, 4, 5** lengkap dan berurutan, tanpa bilangan hilang atau tersisip setelah koreksi diri. Jeda diperbolehkan. Jika anak melanjutkan sesudah lima, nilai hanya segmen 1–5.'),
  (2, 3, 'E1', 'Mengenali lambang bilangan 1–5.', 'Minta menunjuk angka yang disebut. Ucapkan 4; 1; 5; 2; 4; 3, satu per satu.', 'Deret pilihan **3 1 5 2 4**, tetap terlihat. Tidak ada pilihan di luar 1–5.', '**5 dari 6** penunjukan tepat. Kunci **4; 1; 5; 2; 4; 3**.'),
  (3, 3, 'E1', 'Mengenali lambang bilangan 6–10.', 'Dengan prosedur sama, ucapkan 8; 6; 10; 7; 8; 9.', 'Deret **9 6 4 10 7 8**. Angka `4` pengecoh dari cakupan sebelumnya.', '**5 dari 6** tepat. Kunci **8; 6; 10; 7; 8; 9**.'),
  (4, 3, 'E1', 'Menentukan bilangan sebelum atau sesudah suatu bilangan dalam rentang 0–10.', 'Tampilkan satu angka setiap butir. Tanyakan bilangan tepat sebelum atau tepat sesudah angka itu; anak menyebut jawabannya.', '**7: sebelum; 0: sesudah; 9: sesudah; 4: sebelum.** Tanpa deret lengkap atau benda hitung.', '**3 dari 4** tepat. Kunci **6; 1; 10; 3**. Semua masukan dan jawaban tetap dalam 0–10.'),
  (5, 3, 'E1', 'Mengenali lambang bilangan 11–20.', 'Minta menunjuk angka yang disebut: 14; 20; 11; 17; 13; 19; 12; 16; 14; 18; 15.', 'Tiga baris pilihan: **17 12 20 15 / 11 9 18 13 / 16 19 10 14**. Garis miring menandai pergantian baris dalam dokumen, tidak ditulis. `9/10` pengecoh.', '**10 dari 11** tepat. Kunci mengikuti urutan sebutan. Seluruh sepuluh lambang sasaran diperiksa; `14` diulang untuk mengurangi eliminasi.'),
  (6, 3, 'E1', 'Membandingkan nilai dua lambang bilangan dalam rentang 0–20.', 'Tampilkan pasangan satu per satu. Tanyakan, “Mana yang nilainya lebih besar?” Anak menunjuk satu lambang. Tidak meminta tanda `>` atau penjelasan lisan.', '**14–17; 20–13; 8–6; 18–20; 19–12; 0–5.** Setiap pasangan ditampilkan sebagai dua angka berdampingan, sama tinggi dan sama jumlah digit.', '**5 dari 6** tepat. Kunci **17; 20; 8; 20; 19; 5**. Posisi jawaban kanan, kiri, kiri, kanan, kiri, kanan.'),
  (7, 3, 'E1', 'Menentukan posisi bilangan pada garis bilangan 0–20.', 'Tampilkan target tertulis satu per satu, terpisah dari garis. Minta, “Tunjuk tempat bilangan ini pada garis.” Guru tidak membilangkan takik.', 'Garis sesuai Penyiapan Khusus; target **7; 16; 3; 12**. Hanya satu target terlihat setiap butir.', '**3 dari 4** takik tepat: masing-masing 7, 16, 3, dan 12 langkah satuan dari takik 0. Menunjuk label yang sama pada lembar lain bukan jawaban posisi.'),
  (8, 3, 'E1', 'Melanjutkan barisan lambang bilangan dua-dua sampai 20.', 'Tampilkan satu baris setiap butir. Katakan, “Lanjutkan dengan hitungan dua-dua. Sebutkan dua bilangan berikutnya.” Guru tidak membacakan awalan dan tidak menuliskan jawaban pertama sambil menunggu jawaban kedua.', '**4, 6, 8, …, …; 7, 9, 11, …, …; 12, 14, 16, …, …; 9, 11, 13, …, ….**', '**3 dari 4** baris, dengan kedua bilangan lanjutan tepat dan berurutan. Kunci **10–12; 13–15; 18–20; 15–17**. Dua baris genap dan dua ganjil membuat ambang mengharuskan sedikitnya satu baris tepat dari masing-masing jenis.'),
  (1, 9, 'E2', 'Menentukan banyak benda 1–3 dengan korespondensi satu-satu.', 'Tampilkan setiap kumpulan tanpa menyebut jumlahnya. Minta, “Hitung bendanya satu-satu,” kemudian, “Semuanya ada berapa?” Penelusuran benda wajib sesuai ketentuan bersama.', 'Empat kumpulan: **2-R; 1 di tengah; 3-M; 2-S**.', '**3 dari 4** memenuhi satu benda–satu hitungan, urutan hitung tepat, dan jawaban jumlah akhir sesuai. Kunci **2; 1; 3; 2**.'),
  (2, 9, 'E2', 'Menentukan banyak benda 1–5.', 'Tampilkan kumpulan satu per satu tanpa menyebut jumlah. Tanyakan, “Semuanya ada berapa?” Anak boleh menghitung atau menjawab langsung.', '**4-R; 5-S; 5-M; 4-S.** Bahan menekankan perluasan ke empat dan lima, bukan mengulang hanya 1–3.', '**3 dari 4** jumlah akhir tepat. Kunci **4; 5; 5; 4**. Penunjukan saat menghitung tidak wajib; jawaban tidak boleh hanya rangkaian hitung tanpa menetapkan jumlah.'),
  (3, 9, 'E2', 'Menentukan banyak benda 6–10.', 'Prosedur seperti L2, dengan lima kumpulan. Benda boleh ditata ulang sendiri untuk membantu menghitung, tanpa mengubah total.', '**8-R; 6-S; 10-M; 7-S; 9-R.**', '**4 dari 5** jumlah akhir tepat. Kunci **8; 6; 10; 7; 9**. Lima butir mencakup seluruh jumlah 6–10.'),
  (4, 9, 'E2', 'Membagi kumpulan benda dengan total sampai 5 menjadi dua bagian.', 'Guru menyebut total yang sudah disiapkan. Minta, “Pisahkan semua benda menjadi dua kelompok. Kedua kelompok harus berisi benda. Banyaknya boleh kamu pilih.” Setelah selesai, tanyakan banyak benda pada masing-masing kelompok.', 'Total **4; 2; 5; 3**; satu kumpulan awal dan dua wadah kosong polos. Tidak menentukan banyak benda pada salah satu bagian.', '**3 dari 4** pembagian memenuhi: seluruh benda berada dalam dua bagian tak-kosong, total tetap, dan kedua sebutan jumlah tepat. Kunci 2 → 1+1; 3 → 1+2; 4 → 1+3 atau 2+2; 5 → 1+4 atau 2+3. Urutan bagian boleh tertukar.'),
  (5, 9, 'E2', 'Membagi kumpulan benda dengan total sampai 10 menjadi dua bagian.', 'Prosedur sama dengan L4; pembagian tetap bebas dan konkret. Tidak meminta persamaan atau menanyakan bagian yang hilang tanpa benda.', 'Total **6; 8; 7; 10**; dua wadah kosong polos.', '**3 dari 4** memenuhi rubrik pembagian. Kunci 6: 1+5, 2+4, 3+3; 7: 1+6, 2+5, 3+4; 8: 1+7, 2+6, 3+5, 4+4; 10: 1+9, 2+8, 3+7, 4+6, 5+5. Urutan bagian bebas.'),
  (6, 9, 'E2', 'Merepresentasikan bilangan 11–20 secara konkret sebagai satu kelompok sepuluh beserta satuan sisanya.', 'Guru menyebut total kumpulan. Minta anak menempatkan sepuluh benda dalam satu wadah, membiarkan sisanya di luar, lalu menyebut banyak benda di luar. Semua benda tetap tersedia; lakukan tiga butir.', 'Kumpulan **11; 14; 20**; satu wadah kosong dan area sisa yang terlihat. Tidak menyediakan kelompok sepuluh yang sudah jadi.', '**3 dari 3** tepat: wadah berisi sepuluh, seluruh sisa dipertahankan, dan sebutan sisanya benar. Kunci **10 dalam + 1 luar; 10+4; 10+10**. Sisa benar tetapi kelompok utama bukan sepuluh belum memenuhi butir.'),
  (7, 9, 'E2', 'Merepresentasikan bilangan 11–20 secara simbolik sebagai 10 + n.', 'Tampilkan satu bentuk setiap butir. Gunakan hanya perintah baku (Penyiapan Khusus). Anak menyebut bilangan pengisi; guru mencatat tanpa membantu.', '**13 = 10 + …; 20 = 10 + …; 16 = 10 + …; 11 = 10 + ….** Total selalu terlihat; tanpa benda hitung dan tanpa guru membacakan bilangan sasaran.', '**3 dari 4** tepat, dan **butir 20 wajib tepat**. Kunci bagian kosong **3; 10; 6; 1**. Syarat 20 mencegah penyalinan digit paling kanan saja cukup untuk lulus.'),
  (8, 9, 'E2', 'Menentukan nilai digit berdasarkan posisinya pada bilangan 11–20.', 'Tampilkan seluruh bilangan dengan satu digit digarisbawahi. Tanyakan, “Angka yang digarisbawahi ini nilainya berapa?” Anak menyebut nilai, bukan hanya nama tempat atau bentuk digit.', '**14: digit 1; 11: digit 1 kanan; 20: digit 2; 16: digit 6; 20: digit 0.** Keterangan sesudah titik dua hanya untuk guru; pada bahan cukup garis bawah.', '**4 dari 5** tepat. Kunci **10; 1; 20; 6; 0**. “Satu puluhan” diterima untuk 10 dan “dua puluhan” untuk 20; “puluhan” saja belum menyatakan nilai.'),
  (1, 6, 'F1', 'Mengelompokkan benda berdasarkan satu atribut yang sama.', 'Berikan dua set berturut-turut. Set 1: guru berkata, “Kelompokkan berdasarkan warna.” Set 2: guru berkata, “Kelompokkan berdasarkan ukuran.” Anak menyusun benda menjadi kelompok.', 'Set 1: empat balok sama bentuk dan ukuran, hanya warna berbeda, **2 merah dan 2 biru**. Set 2: empat balok sama bentuk dan warna, hanya ukuran berbeda, **2 besar dan 2 kecil**.', '**2 dari 2 set** tepat. Kunci Set 1: merah bersama dan biru bersama. Kunci Set 2: besar bersama dan kecil bersama. Semua benda digunakan, tanpa kelompok campur.'),
  (2, 6, 'F1', 'Mengenali bentuk datar dasar.', 'Guru menampilkan satu susunan per butir dan berkata, “Tunjuk [nama bentuk].” Anak menunjuk bentuk yang disebut.', 'Enam butir goresan geometris polos, pilihan kiri–kanan. **B1:** segitiga, persegi, lingkaran, persegi panjang; tanya lingkaran. **B2:** lingkaran, persegi panjang, segitiga, persegi diputar; tanya persegi. **B3:** persegi, lingkaran, persegi panjang, segitiga; tanya persegi panjang. **B4:** persegi panjang, segitiga, lingkaran, persegi; tanya segitiga. **B5:** persegi panjang, lingkaran, persegi, segitiga; tanya persegi. **B6:** segitiga, persegi panjang, persegi, lingkaran; tanya persegi panjang.', '**5 dari 6** tepat. Kunci posisi: **3; 4; 3; 2; 3; 2**. Persegi dan persegi panjang hadir bersama; persegi yang diputar pada butir 2 tetap persegi.'),
  (3, 6, 'F1', 'Melanjutkan pola berulang AB.', 'Pada tiap butir guru menata tiga unit pola, lalu berkata, “Lanjutkan dengan dua benda berikutnya.” Anak meletakkan dua balok lanjutan.', 'Empat deret balok warna, satu modalitas saja: **merah-biru; kuning-hijau; putih-hitam; merah-kuning**, masing-masing diulang 3 kali.', '**3 dari 4 deret** tepat. Kunci lanjutan: **merah-biru; kuning-hijau; putih-hitam; merah-kuning**. Mengulang benda terakhir tidak memenuhi butir.'),
  (4, 6, 'F1', 'Melanjutkan pola berulang ABC.', 'Pada tiap butir guru menata tiga unit pola, lalu berkata, “Lanjutkan dengan tiga benda berikutnya.” Anak meletakkan tiga balok lanjutan.', 'Empat deret balok warna, tanpa campuran modalitas: **merah-biru-hijau; kuning-putih-hitam; biru-merah-kuning; hijau-putih-merah**, masing-masing diulang 3 kali.', '**3 dari 4 deret** tepat. Kunci lanjutan: **merah-biru-hijau; kuning-putih-hitam; biru-merah-kuning; hijau-putih-merah**. Pola AAB/ABB tidak digunakan; jawaban ABAB belum memenuhi.'),
  (5, 6, 'F1', 'Membandingkan panjang dua benda secara langsung.', 'Guru menampilkan empat pasangan satu per satu. Dua benda diletakkan atas-bawah dengan ujung kiri sejajar. Tanyakan, “Mana yang lebih panjang?” Anak menunjuk satu benda.', 'Potongan stik polos sama lebar dan tebal. Panjang atas-bawah: **8-12; 14-10; 9-13; 11-15 cm**. Tidak ada penggaris saat asesmen.', '**3 dari 4** tepat. Kunci posisi benda lebih panjang: **bawah; atas; bawah; bawah**. Beda panjang harus terlihat jelas; lebar, warna, dan ketebalan tidak menjadi dasar skor.'),
  (6, 6, 'F1', 'Mengurutkan tiga atau lebih benda berdasarkan panjang.', 'Berikan tiga set bergantian. Pada tiap set, minta, “Susun dari yang paling pendek sampai paling panjang.” Anak menyusun benda.', 'Tiga set potongan stik polos sama lebar dan tebal. Set 1: kira-kira **6, 10, 14 cm**; Set 2: **8, 12, 16 cm**; Set 3: **7, 11, 15 cm**. Urutan awal diacak.', '**2 dari 3 set** seluruh posisinya benar. Kunci tiap set dari kiri ke kanan setelah disusun: **terpendek-sedang-terpanjang**.'),
  (7, 6, 'F1', 'Mengukur panjang benda menggunakan satuan tidak baku yang seragam.', 'Guru memberi satu benda target dan satuan ukur. Anak meletakkan satuan berurutan dari ujung ke ujung, lalu menyebut jumlah satuan. Lakukan tiga butir.', 'Satuan berupa balok kecil/penjepit yang sama ukuran. Target utama berupa tiga pita kertas polos sepanjang **4 satuan; 6 satuan; 5 satuan**.', '**2 dari 3** tepat. Kunci: **4; 6; 5 satuan**. Per butir mendapat poin bila satuan seragam, disusun berurutan tanpa celah/tumpang tindih lebih dari seperempat satuan, dan jumlah disebut tepat. Bila panjang target meleset lebih dari seperempat satuan dari kunci saat persiapan, bahan diganti sebelum tes.'),
  (8, 6, 'F1', 'Memperkirakan panjang benda dalam satuan tidak baku.', 'Guru menunjukkan benda target dan satu satuan contoh yang diletakkan terpisah. Anak menyebut perkiraan dahulu. Setelah jawaban final, guru mengukur untuk memeriksa ketepatan.', 'Satuan sama jenis dengan L7, tetapi target utama bukan benda target L7: tiga tali rafia polos yang ditegangkan lurus sepanjang **5 satuan; 8 satuan; 11 satuan**. Satuan contoh berada di samping, tidak menempel target dan tidak boleh dipegang anak.', '**2 dari 3** perkiraan dalam toleransi **±20% dari panjang aktual, dibulatkan ke bilangan bulat terdekat**. Kunci diterima: **5 satuan = 4-6; 8 satuan = 6-10; 11 satuan = 9-13**. Pengukuran aktual hanya prosedur pemeriksaan, bukan kemampuan kedua.'),
  (1, 12, 'F2', 'Menentukan jumlah setelah satu benda ditambahkan pada kelompok kecil.', 'Tiap butir: guru memperlihatkan kelompok awal, menyebut jumlah awal, menutup kelompok dengan kain/wadah terbalik polos, memasukkan satu benda tambahan ke bawah penutup secara terlihat, lalu bertanya, “Sekarang ada berapa?” Penutup tetap tertutup sampai jawaban dicatat.', 'Balok polos dan penutup. Empat peristiwa: **1 tambah 1; 2 tambah 1; 1 tambah 1; 2 tambah 1**. Hasil paling banyak 3.', '**3 dari 4** tepat. Kunci: **2; 3; 2; 3**.'),
  (2, 12, 'F2', 'Menentukan jumlah setelah satu benda diambil dari kelompok kecil.', 'Guru memperlihatkan dan menyebut jumlah awal, menutup kelompok, mengeluarkan satu benda dari bawah penutup secara terlihat lalu menyingkirkannya, kemudian bertanya jumlah sekarang tanpa membuka penutup.', 'Balok polos dan penutup. Empat peristiwa: **3 ambil 1; 5 ambil 1; 2 ambil 1; 4 ambil 1**. Awal paling banyak 5.', '**3 dari 4** tepat. Kunci: **2; 4; 1; 3**.'),
  (3, 12, 'F2', 'Menentukan jumlah setelah dua kelompok konkret digabungkan.', 'Guru memperlihatkan dua kelompok terpisah dan menyebut banyaknya masing-masing. Tutup kedua kelompok dengan satu kain lebar, lalu rapatkan/gabungkan kedua kelompok di bawah kain tanpa memperlihatkan benda. Tanyakan, “Semuanya sekarang ada berapa?”', 'Balok polos dan kain penutup lebar. Empat gabungan: **2 dan 3; 1 dan 3; 2 dan 2; 1 dan 4**. Hasil paling banyak 5.', '**3 dari 4** tepat. Kunci: **5; 4; 4; 5**.'),
  (4, 12, 'F2', 'Menentukan jumlah setelah beberapa benda diambil dari satu kelompok konkret.', 'Guru memperlihatkan dan menyebut jumlah awal, menutup kelompok, mengeluarkan beberapa benda dari bawah penutup secara terlihat lalu menyingkirkannya, kemudian bertanya jumlah sekarang tanpa membuka penutup.', 'Balok polos dan penutup. Empat peristiwa: **5 ambil 2; 4 ambil 2; 5 ambil 3; 3 ambil 2**. Awal paling banyak 5.', '**3 dari 4** tepat. Kunci: **3; 2; 2; 1**.'),
  (5, 12, 'F2', 'Menentukan hasil penjumlahan dalam 10 pada representasi simbolik.', 'Guru menulis satu kalimat angka setiap butir, menunjuk seluruhnya, dan bertanya, “Berapa hasilnya?” Tidak ada peragaan cerita. Sepuluh benda penopang selalu tersedia di sisi meja.', 'Tulisan guru: **3 + 4 = ...; 5 + 2 = ...; 6 + 4 = ...; 1 + 8 = ...; 4 + 5 = ...**.', '**4 dari 5** tepat. Kunci: **7; 7; 10; 9; 9**. Anak boleh menyebut jawaban atau memakai benda penopang lalu menyebut hasil.'),
  (6, 12, 'F2', 'Menentukan hasil pengurangan dalam 10 pada representasi simbolik.', 'Prosedur sama dengan L5; guru menulis bentuk pengurangan. Tidak ada peristiwa mengambil benda oleh guru. Sepuluh benda penopang selalu tersedia.', 'Tulisan guru: **9 − 4 = ...; 8 − 6 = ...; 10 − 3 = ...; 7 − 4 = ...; 6 − 5 = ...**.', '**4 dari 5** tepat. Kunci: **5; 2; 7; 3; 1**.'),
  (7, 12, 'F2', 'Menentukan hasil penjumlahan yang melewati 10, hasil paling banyak 20, tanpa benda hitung yang disediakan.', 'Guru menulis satu kalimat angka setiap butir dan bertanya, “Berapa hasilnya?” Tidak menyediakan benda hitung; jari anak boleh dipakai.', 'Tulisan guru: **8 + 5 = ...; 9 + 6 = ...; 7 + 5 = ...; 8 + 8 = ...; 9 + 9 = ...**. Semua butir melewati 10 dan hasil paling banyak 20.', '**4 dari 5** tepat. Kunci: **13; 15; 12; 16; 18**.'),
  (8, 12, 'F2', 'Menentukan hasil pengurangan yang melewati 10, bilangan awal paling banyak 20, tanpa benda hitung yang disediakan.', 'Guru menulis satu kalimat angka setiap butir dan bertanya, “Berapa hasilnya?” Tidak menyediakan benda hitung; jari anak boleh dipakai.', 'Tulisan guru: **13 − 5 = ...; 12 − 4 = ...; 16 − 7 = ...; 15 − 8 = ...; 14 − 9 = ...**. Semua butir memerlukan pengurangan melewati 10; bilangan awal paling banyak 20.', '**4 dari 5** tepat. Kunci: **8; 8; 9; 7; 5**.'),
  (1, 13, 'EN', 'Merespons ungkapan kelas sangat pendek dalam bahasa Inggris yang diucapkan guru.', 'Anak mulai duduk. Guru mengucapkan enam stimulus: **sit down; stand up; stand up; hello; sit down; goodbye**. Untuk hello/goodbye anak menjawab dengan ucapan sesuai; untuk sit down/stand up anak melakukan atau mempertahankan posisi.', 'Kursi; stimulus tetap **hello, goodbye, sit down, stand up**.', '**5 dari 6** tepat dan kedua butir hello/goodbye tepat. Kunci: tetap duduk; berdiri; tetap berdiri; **hello/hi**; duduk; **goodbye/bye**. Lambaian tanpa ucapan tidak mendapat poin untuk hello/goodbye.'),
  (2, 13, 'EN', 'Menghubungkan kata Inggris tertulis utuh dengan benda konkret yang sesuai.', 'Dari daftar layak uji, guru memilih **4 kata benda** pertama yang bendanya tersedia. Nomori menurut urutan daftar tema. Tulis enam butir dengan urutan indeks **2-4-1-3-2-1**. Anak menunjuk benda.', 'Empat benda nyata sesuai kata benda terpilih. Bila benda target berlabel tulisan/merek, tutup tulisan.', '**5 dari 6** tepat. Kunci mengikuti kata yang ditulis. Membaca nyaring tidak diwajibkan.'),
  (3, 13, 'EN', 'Menyebut nama benda konkret dalam bahasa Inggris.', 'Dari daftar layak uji, guru memilih **5 kata benda** pertama yang bendanya tersedia. Tampilkan benda dengan urutan indeks **2-4-1-5-3**. Tiap butir guru bertanya, **“What is this?”**', 'Lima benda nyata dari tema.', '**4 dari 5** tepat. Kunci mengikuti nama English benda yang ditunjukkan.'),
  (4, 13, 'EN', 'Menghubungkan kata warna Inggris tertulis utuh dengan atribut warna benda konkret.', 'Guru menyiapkan benda tema berwarna merah, biru, hijau, kuning, dan hitam. Guru menulis enam kata warna dengan urutan **blue; red; yellow; black; green; red**. Anak menunjuk benda berwarna sesuai.', 'Lima benda tema atau benda tema yang diberi penanda warna polos. Warna tetap: **red, blue, green, yellow, black**.', '**5 dari 6** tepat. Kunci: biru; merah; kuning; hitam; hijau; merah.'),
  (5, 13, 'EN', 'Mengucapkan satu ungkapan kebutuhan sederhana dalam bahasa Inggris.', 'Dari daftar layak uji, guru memilih **4 kata benda bertanda wajar diminta** pertama yang bendanya tersedia. Tampilkan benda sasaran satu per satu dengan urutan indeks **2-4-1-3** dan bertanya, **“What do you want?”**', 'Empat benda nyata bertanda wajar diminta dari tema.', '**3 dari 4** tepat. Kunci: **I want [kata benda English]** atau **I want a/an [kata benda English]** sesuai benda. Penghilangan **I want** belum memenuhi.'),
  (6, 13, 'EN', 'Menghubungkan frasa tindakan Inggris tertulis utuh dengan tindakan konkret yang sesuai.', 'Dari daftar layak uji, guru memilih **4 frasa tindakan** pertama yang dapat diperagakan. Tulis enam butir dengan urutan indeks **3-1-4-2-1-3**. Anak melakukan tindakan.', 'Benda nyata yang diperlukan untuk frasa tindakan tema.', '**5 dari 6** tepat. Kunci mengikuti tindakan yang ditulis. Anak tidak wajib membaca nyaring.'),
  (7, 13, 'EN', 'Menjawab pertanyaan personal rutin dalam bahasa Inggris dengan jawaban berpola.', 'Guru bertanya empat kali: **What is your name?; How are you?; How are you?; What is your name?**', 'Pertanyaan lisan tetap.', '**3 dari 4** tepat. Kunci: **My name is [nama anak]** atau **My name’s [nama anak]**; **I am fine** atau **I’m fine**. Nama panggilan sebenarnya diterima. “Fine” saja belum memenuhi pola L7.'),
  (8, 13, 'EN', 'Menentukan makna literal dari kalimat Inggris sangat pendek.', 'Dari daftar layak uji, guru memilih **4 kata benda** pertama yang bendanya tersedia. Guru membuat empat kalimat dengan pola: **This is a red [2].; I see a blue [4].; This is a green [1].; I see a yellow [3].** Anak menunjuk benda sesuai.', 'Untuk tiap kata benda sasaran, sediakan dua referen: warna target dan satu warna pengecoh lain. Benda boleh diberi penanda warna polos bila warna asli tidak tersedia.', '**3 dari 4** tepat. Kunci mengikuti warna + benda dalam kalimat. Anak tidak diminta menirukan atau membaca nyaring; yang dinilai pemahaman makna literal.'),
  (1, 14, 'KR', 'Mengucapkan atau menjawab salam Islami sederhana dalam pembukaan atau penutupan sesi.', 'Pada awal atau akhir sesi, guru memberi salam Islami satu kali dan memberi jeda wajar. Bila anak lebih dulu memberi salam Islami, itu juga dapat menjadi bukti.', 'Situasi pembukaan/penutupan; tanpa bahan khusus.', 'Lulus bila anak mengucapkan atau menjawab **assalamu''alaikum/wa''alaikumussalam** atau padanan pelafalan anak yang jelas. “Halo” atau “selamat pagi” belum memenuhi.'),
  (2, 14, 'KR', 'Mengikuti adab doa pendek sebelum belajar dengan basmalah atau doa belajar pendek.', 'Pada pembukaan belajar, guru berkata, “Kita mulai belajar dengan doa.” Guru tidak menuntut hafalan panjang. Anak diberi kesempatan mengikuti adab doa pendek.', 'Situasi pembukaan belajar.', 'Lulus bila anak mengucapkan **bismillah/basmalah** atau doa belajar pendek yang dikenali. Diam, bercanda, atau hanya menirukan gerak tanpa ucapan belum memenuhi; panjang dan kefasihan doa tidak dinilai.'),
  (3, 14, 'KR', 'Mengucapkan terima kasih setelah menerima bantuan atau benda dari guru.', 'Dalam satu sesi, guru menyediakan dua kesempatan wajar: memberi anak benda yang dibutuhkan dan/atau membantu menyiapkan sesuatu. Setelah tiap bantuan, guru memberi jeda tanpa memerintah “bilang terima kasih.”', 'Benda nyata yang relevan, misalnya pensil, penghapus, buku, atau gelas.', 'Lulus bila anak mengucapkan **terima kasih/makasih** atau padanan sopan yang jelas pada sedikitnya **1 dari 2** kesempatan. Jika hanya satu kesempatan wajar muncul, satu kesempatan itu boleh dinilai; jika tidak ada kesempatan wajar, asesmen belum terlaksana.'),
  (4, 14, 'KR', 'Mengucapkan maaf dalam main peran ringan tentang kesalahan kecil.', 'Guru membuat main peran singkat dengan benda: “Boneka ini tidak sengaja menjatuhkan pensil temannya. Kalau kamu jadi boneka, apa yang kamu katakan?” Tidak memakai kesalahan nyata anak.', 'Boneka/benda peran polos, pensil.', 'Lulus bila anak mengucapkan **maaf** atau kalimat permintaan maaf setara dalam konteks main peran. Batas tafsir: Lulus menunjukkan anak dapat memakai ungkapan maaf pada skenario ringan, bukan bukti perilaku nyata di semua situasi.'),
  (5, 14, 'KR', 'Menunggu giliran dalam simulasi bergantian singkat dengan guru.', 'Guru dan anak bermain giliran mengambil/meletakkan benda selama tiga putaran. Guru berkata di awal, “Kita bergantian. Ibu dulu, lalu kamu.” Setelah itu guru menjalankan giliran tanpa mengingatkan setiap putaran.', 'Empat balok polos dan dua wadah.', 'Lulus bila anak menunggu giliran guru selesai pada sedikitnya **2 dari 3** kesempatan giliran, tanpa mengambil benda sebelum gilirannya. Gelisah ringan atau bertanya netral tidak menggagalkan.'),
  (6, 14, 'KR', 'Merapikan alat belajar yang baru dipakai setelah kegiatan selesai.', 'Setelah tugas memakai alat selesai, guru memberi isyarat akhir kegiatan, misalnya “Kegiatannya selesai,” dan tempat alat sudah terlihat. Guru tidak memberi perintah langsung “rapikan alat.” Amati hingga sekitar 30 detik.', 'Alat yang baru dipakai, misalnya pensil, buku, balok; wadah/tempat penyimpanan jelas.', 'Lulus bila anak mengembalikan alat utama yang dipakai ke tempat yang ditentukan tanpa instruksi langkah demi langkah. Belum bila baru merapikan setelah perintah langsung atau alat dibiarkan tercecer.'),
  (7, 14, 'KR', 'Menyatakan dengan benar apakah tugasnya sudah atau belum selesai ketika ditanya netral oleh guru.', 'Guru memilih tugas singkat yang dapat diselesaikan wajar. Tanyakan netral dua kali: pertama saat tugas jelas belum selesai, kedua setelah tugas benar-benar selesai. Tidak ada hadiah/hukuman atas isi jawaban.', 'Tugas kelas singkat yang dapat diverifikasi, misalnya memasukkan tiga balok ke wadah atau menyusun tiga benda.', 'Lulus bila kedua jawaban sesuai keadaan: menjawab **belum** saat tugas belum selesai dan **sudah** saat tugas selesai. Jawaban bercanda/asal yang tidak sesuai belum memenuhi. Batas tafsir: Lulus menunjukkan kesesuaian jawaban pada skenario netral, bukan bukti menyeluruh tentang kejujuran anak.'),
  (8, 14, 'KR', 'Menjalankan rutinitas kerja pendek yang sudah dikenal tanpa bantuan langkah demi langkah.', 'Pada anak yang sudah mengikuti kelas, amati satu rutinitas yang sudah biasa dilakukan: mengambil alat, mengerjakan tugas pendek, lalu mengembalikan alat. Guru hanya memberi isyarat umum rutinitas, bukan instruksi langkah demi langkah. Pada anak baru, situasi ini dapat belum terlaksana.', 'Rutinitas kelas yang sudah dikenal; alat sederhana dan tempat penyimpanan tetap.', 'Lulus bila anak menyelesaikan tiga bagian rutinitas: **mengambil alat yang sesuai; memulai/menjalankan tugas pendek; mengembalikan alat**, tanpa bantuan langkah demi langkah. Ini menilai kemandirian rutinitas, bukan memahami instruksi lisan baru.');

insert into public.k8_notes(doc, position, title, markdown) values
  ('A', 1, 'Ketentuan Bersama', '- Setiap indikator dirancang untuk pelaksanaan sekitar satu menit. Durasi tersebut merupakan sasaran rancangan, belum hasil verifikasi lapangan. Bahan berupa tuturan, peristiwa langsung, dan benda nyata, tanpa kartu, lembar kerja, atau gambar/bahan cetak.
- Guru memastikan anak mengikuti tuturan atau peristiwa sebelum menilai. Gangguan yang membuat bahan tidak terdengar atau tidak terlihat ditangani terlebih dahulu. Tuturan yang tidak tersampaikan utuh akibat gangguan disampaikan ulang secara utuh, tanpa dipecah menjadi petunjuk jawaban. Pada A1, jawaban singkat dan padanan makna diterima; kalimat lengkap tidak diwajibkan.
- A2 L4–L8 memakai satu peristiwa dan satu sampel tuturan yang dinilai. Pada A2 L2–L8, guru boleh memberikan satu pancingan netral per kesempatan: **“Masih ada yang mau kamu ceritakan?”** Pancingan tidak menyebut unsur yang kurang. Respons tambahan tetap bagian dari sampel yang sama. Tidak digunakan aturan otomatis dua peristiwa lalu memilih hasil terbaik.
- Untuk menghitung kalimat lisan A2, periksa klausa yang menyatakan tindakan atau keadaan. Klausa tindakan berbeda yang dihubungkan *terus/lalu/dan* dihitung terpisah: **“Ibu ambil buku terus masukin ke tas”** memuat dua klausa tindakan. **“Buku dan tas”** bukan dua klausa. Pengulangan isi yang sama tidak menambah hitungan. Panjang jeda tidak menentukan hitungan. Subjek boleh tersirat jika rujukannya jelas.
- Centang diberikan untuk informasi yang dinyatakan dalam klausa, bukan sekadar kata yang disebut. Pelafalan dan ragam percakapan diterima selama makna serta fungsi bahasa yang menjadi sasaran tetap terpenuhi. Guru tidak mencontohkan kalimat jawaban atau memberikan kata penghubung sasaran.
- Peragaan, penataan benda, dan tindakan untuk menyediakan pengalaman A2 tidak diberi skor. Guru boleh membantu gerakan tanpa memberikan narasi contoh. Ketepatan gerakan, termasuk ketepatan lipatan kain, tidak dinilai. Pada tugas pengalaman anak, anak tetap terlibat dalam rangkaian yang diceritakan.
- Jika anak belum bersedia mengikuti tes atau pelaksanaannya terputus, kesempatan tersebut belum menjadi bukti **Belum**. Pengambilan sampel dilakukan kembali ketika tes dapat terlaksana. Untuk tahap implementasi, asesmen yang belum terlaksana perlu dibedakan dari hasil akademik Belum tanpa mengubah catatan kehadiran anak; bentuk dukungan aplikasinya ditetapkan kemudian.'),
  ('A', 2, 'A2: Menghasilkan Bahasa Lisan', '### Rincian Tanda Lulus A2 L8

| Unsur | Bukti yang memenuhi |
|---|---|
| **Hambatan** | Anak menyatakan **upaya memasukkan bola yang belum berhasil**, atau **keadaan penghalang yang dikaitkan dengan upaya tersebut**. Contoh: “bolanya nggak bisa masuk”; “mau masukin bola tapi kotaknya ketutup”. Hubungan dengan upaya harus terungkap dalam tuturan anak. Penghalang yang disebut tanpa kaitan tersebut belum memenuhi unsur. |
| **Tindakan mengatasi** | Anak menyatakan kotak atau tutupnya dibuka. |
| **Hasil akhir** | Anak menyatakan bola berhasil masuk atau sudah berada di dalam kotak. Ucapan “selesai” saja belum memenuhi unsur. |
| **Urutan** | Hambatan mendahului tindakan mengatasi, kemudian hasil akhir. |

### Contoh Kalibrasi A2 L8

Digunakan guru untuk menyamakan penilaian; tidak dibacakan kepada anak sebelum tes. Keputusan Belum di sini berlaku terhadap bukti yang disyaratkan indikator, bukan kesimpulan bahwa anak tidak mampu bercerita secara umum.

| Contoh tuturan | Keputusan dan alasan |
|---|---|
| “Bolanya nggak bisa masuk. Kotaknya dibuka. Terus bolanya masuk.” | **Lulus:** hambatan, tindakan, hasil, dan urutan terungkap. |
| “Mau masukin bola, tapi kotaknya ketutup. Terus tutupnya dibuka. Jadi bolanya bisa masuk.” | **Lulus:** keadaan penghalang dikaitkan dengan upaya; tindakan dan hasil dinyatakan. |
| “Tutupnya bikin bola nggak bisa masuk. Bu Guru buka kotaknya. Bolanya sekarang di dalam kotak.” | **Lulus:** hubungan hambatan terhadap tujuan dan penyelesaiannya dinyatakan. |
| “Kotaknya ketutup, terus dibuka, bolanya masuk.” | **Belum:** rangkaian kejadian dan hasil sudah ada, tetapi kaitan keadaan tertutup dengan upaya yang terhalang belum dinyatakan. |
| “Bolanya nggak bisa masuk. Bu Guru buka kotaknya.” | **Belum:** hasil akhir belum diceritakan dan sampel belum memuat tiga klausa. |'),
  ('A', 3, 'Bahan Cadangan', 'Dipilih sebelum tes sebagai alternatif bahan untuk satu pelaksanaan. Fungsi indikator, jumlah respons/klausa, dan ambang kelulusan tetap mengikuti indikator terkait; kunci isi disesuaikan dengan benda atau peristiwa cadangan berikut.

| Penggunaan | Bahan atau peristiwa cadangan | Penerapan penilaian |
|---|---|---|
| **A2 L1 dan L3** | Botol polos, piring plastik, tas polos, kain. | L1: penamaan benda, **3 dari 4**. L3: klausa yang menyebut benda dan ciri fisik yang dapat diperiksa langsung, **3 dari 4**. |
| **A2 L4** | Guru **mengambil kain → melipat kain**, tanpa narasi. | Sedikitnya **dua klausa berbeda**: pengambilan kain dan pelipatan kain, merujuk kejadian yang sama. Urutan penceritaan belum menjadi syarat tambahan. |
| **A2 L5** | Anak **mengambil kain → melipat kain → menaruh kain di kotak**, dengan arahan nonverbal. | Sedikitnya **tiga klausa berbeda** yang menyatakan ketiga tindakan dalam urutan sesuai kejadian. Anak tetap terlibat; bantuan gerak diperbolehkan tanpa narasi contoh. Ketepatan lipatan tidak dinilai. |
| **A2 L7** | Guru menggeser kain hingga jatuh; anak **mengambil kain → mengembalikannya ke meja**. | Unsur cerita: **kain jatuh; kain diambil; kain dikembalikan; urutan sesuai**, dalam sedikitnya tiga klausa, ditambah hubungan sebab yang sesuai dengan penghubung sebab setara. Sebab yang diterima: kain jatuh karena tergeser, atau diambil karena jatuh/berada di lantai. |
| **A2 L8** | Guru **mencoba minum dari gelas kosong → mengisi air → minum**, tanpa narasi. | Sedikitnya tiga klausa. **Hambatan:** belum bisa minum, atau gelas kosong dikaitkan dengan upaya minum. **Tindakan:** mengisi air. **Hasil:** guru berhasil/bisa minum. Urutan sesuai. Menyebut “gelas kosong” tanpa kaitan dengan upaya minum belum memenuhi unsur hambatan. |

**Aturan L5 ≠ L6:** Untuk anak yang sama, set peristiwa beserta benda yang digunakan pada L5 tidak digunakan kembali persis pada L6. Ketentuan berlaku pada bahan utama maupun cadangan. Rangkaian **sendok → gelas → meja ditetapkan khusus untuk L6** dan dikeluarkan dari pilihan cadangan L4–L5. Rangkaian utama **buku → tas → meja** pada L4–L5 tetap; cadangan L4–L5 menggunakan rangkaian kain sesuai tabel.'),
  ('B', 1, 'Ketentuan Bersama', '- Guru menulis bahan B1 menjelang asesmen, sebelum anak duduk, pada kesempatan uji yang sama. Tutup sampai digunakan. Tanpa kartu, lembar kerja, atau bahan cetak. Semua pilihan memakai ukuran, warna, dan bentuk tulisan yang konsisten.
- Sasaran interaksi sekitar satu menit per indikator, termasuk pengarahan dan contoh. Persiapan dihitung terpisah. Durasi belum tervalidasi lapangan dan bukan batas waktu kelulusan anak.
- B1 menggunakan tulisan; B2 sepenuhnya lisan. Singkirkan atau tutup tulisan B1 sebelum B2. Semua notasi bunyi, kata, dan kunci B2 di dokumen ini hanya untuk guru, bukan bahan yang dibaca anak.
- Sebelum B1, katakan, **“Kamu boleh menunjuk tulisan yang sama lagi.”** Semua pilihan tetap tersedia. Jangan mencoret, menandai, atau menghilangkan pilihan yang sudah ditunjuk. B1 L1 memakai vokal, L2–L4 memakai bunyi konsonan, dan L5 memakai nama huruf.
- Setiap indikator B2 memakai satu contoh tetap yang tidak dinilai. Guru mencontohkan masukan dan jawabannya sekali, tanpa latihan lanjutan. Contoh tidak menjadi butir paket utama atau cadangan indikator tersebut. Pada masukan berpasangan B2 L1, L3, dan L6, jeda antarunit sekitar satu detik.
- Sampaikan stimulus sekali. Bila tertutup gangguan suara, ulangi utuh tanpa tambahan petunjuk. Jangan memberi pembetulan, menunjuk jawaban, atau menekankan bagian jawaban dalam kata. Stimulus yang tidak tersampaikan dengan benar bukan dasar menilai anak salah.
- Satu butir mendapat satu poin bila respons memenuhi kunci lengkap; kalimat lengkap tidak diperlukan. Gunakan satu paket, bukan hasil terbaik dari dua paket. Anak belum bersedia atau asesmen terputus bukan bukti **Belum**. Perilaku, kepatuhan, dan kehadiran tidak dijadikan pengganti hasil akademik.'),
  ('B', 2, 'Kalibrasi Pelafalan', '- Contoh bagian ini hanya untuk guru. `/m/` berupa dengung “mmm”, bukan “em/ma”; `/s/` berupa desis, bukan “es”. `/e/` pada pasangan vokal menggunakan bunyi seperti awal *ekor*. Nama `q` adalah *qi*, diucapkan “ki”; nama `v` adalah *ve*, diucapkan “fe”. [Acuan nama huruf EYD](https://ejaan.kemendikdasmen.go.id/eyd/penggunaan-huruf/huruf-abjad/).
- Pada `/b/`, `/d/`, `/g/`, `/j/`, pelepasan dengan pepet sangat lemah dapat ditoleransi; bukan suku kata penuh. Tambahan pepet tidak diwajibkan pada `/p/`, `/t/`, `/k/`. **Tambahan untuk B1 L4:** `/c/` memakai bunyi awal *cuci*, boleh dengan pelepasan pepet sangat lemah, bukan nama “ce” atau suku kata “ca”; `/h/` berupa embusan singkat “hhh” yang terdengar, boleh disertai pepet sangat lemah, bukan “ha” atau vokal tanpa embusan.
- Pada pemisahan **bu**, respons `/b/` dengan pelepasan sangat singkat lalu `/u/` diterima. **“Be–u”** sebagai nama huruf, **“bu” saja**, atau **“bu–u”** tidak memenuhi. Pada penggabungan `/b/ … /i/`, hasilnya **bi**, bukan rangkaian dengan vokal tambahan. Toleransi tidak mengubah jumlah unit yang dinilai. *Nga/nya* hanya merupakan konteks pembawa bunyi pada B1 L6, bukan kelonggaran untuk tugas fonem B2.'),
  ('B', 3, 'B1: Pengenalan Grafem', 'B1 memakai enam butir, kecuali L5 yang memakai delapan untuk mencakup tujuh grafem sekaligus pengulangan. Semua ambang menoleransi satu kesalahan. B1 L8 merupakan penguatan khusus sesuai pengecualian arsitektur, bukan klaim kenaikan kesulitan dari diftong. Kata *oi* (koboi, konvoi) dipilih pemilik; tidak diganti secara spontan oleh guru.'),
  ('B', 4, 'Bahan Cadangan', 'Pilih paket sebelum penilaian. Jangan mengganti butir setelah jawaban salah, mencampur skor dua paket, atau otomatis memberikan paket kedua setelah gagal. Contoh tetap mengikuti indikator. Semua paket cadangan B2 berisi empat butir dengan ambang **3 dari 4**.

| Sasaran | Bahan Cadangan dan Kunci |
|---|---|
| B1 L1–L8 | Susunan pilihan tertulis boleh diacak sebelum uji. Inventaris, urutan stimulus, jumlah butir, frekuensi sasaran, dan kunci grafem tetap. Kata `oi` tetap koboi dan konvoi sesuai keputusan pemilik, bukan pilihan spontan guru. |
| B2 L1 | **/i/ … /a/; /o/ … /u/; /a/ … /e/; /u/ … /i/**. Kunci: kedua bunyi ditirukan menurut urutan masing-masing pasangan. |
| B2 L2 | **madu → /m/; nama → /n/; batu → /b/; palu → /p/**. Semua dua suku kata terbuka, dengan sasaran konsonan sama seperti paket utama. |
| B2 L3 | **ta … li → tali; da … du → dadu; san … dal → sandal; pin … tu → pintu**. Struktur sama dengan paket utama: **KV-KV; KV-KV; KVK-KVK; KVK-KV**. |
| B2 L4 | **roda → ro-da; pepaya → pe-pa-ya; keramik → ke-ra-mik; jemputan → jem-pu-tan**. Struktur sama dengan paket utama: **KV-KV; KV-KV-KV; KV-KV-KVK; KVK-KV-KVK**. |
| B2 L5 | **tali tanpa li → ta; sepatu tanpa se → patu; selimut tanpa se → limut; mentimun tanpa mun → menti**. Struktur kata dan posisi penghilangan sama dengan paket utama: **akhir, awal, awal, akhir**. |
| B2 L6 | **/m/ … /u/ → mu; /b/ … /o/ → bo; /s/ … /a/ → sa; /t/ … /i/ → ti**. Inventaris dan komposisi jenis konsonan serta vokal tetap. |
| B2 L7 | **mo → /m/–/o/; ba → /b/–/a/; si → /s/–/i/; tu → /t/–/u/**. Komposisi tetap; pasangan KV tidak mengulang paket L6. |
| B2 L8 | **pagi: /p/ menjadi /b/ → bagi; buku: /b/ menjadi /s/ → suku; dadu: /d/ menjadi /m/ → madu; tamu: /t/ menjadi /k/ → kamu**. Hanya fonem pertama diganti; fonem sama yang muncul kemudian tetap dipertahankan. |'),
  ('B', 5, 'Pemakaian Ulang Kata', 'Gabungan kata utuh dalam paket utama, cadangan, contoh, dan kata hasil pada satu level tidak dipakai kembali pada level tepat sesudahnya dalam slot yang sama. Larangan tidak mencakup grafem, fonem, atau suku kata penyusun; pengecualian B1 L8 tetap berlaku. Penggunaan kembali setelah ada satu level penyela diperbolehkan, tetapi bukan alasan melatih kunci sebelum diagnostik.'),
  ('B', 6, 'Catatan Risiko', '- **Progresi:** L3 mempertahankan dua unit sekaligus menambahkan struktur tertutup; L4 menuntut penentuan batas sendiri dengan sebagian kata lebih panjang; L5 memanipulasi bahan berstruktur sebanding. Pada ketiganya, ambang 3 dari 4 mengharuskan sedikitnya satu respons benar pada kata yang memuat suku kata tertutup. Kenaikan kesulitan L2→L3 tetap perlu kalibrasi lapangan. Risiko L5→L6 dipertahankan sesuai keputusan, tanpa penambahan panjang atau kecepatan.
- **Kesetaraan L5:** pasangan hasil utama/cadangan adalah **ro/ta; neka/patu; lepon/limut; jemba/menti**. Panjang dan struktur sisanya berpasangan sama, serta tidak dipilih sebagai kata akrab. Ini bukan klaim bahwa rangkaian tersebut tidak bermakna dalam setiap bahasa daerah atau nama diri. Keakraban individual tidak mengubah kunci; temuan lokal menjadi bahan evaluasi paket, bukan pergantian butir saat tes.
- **Pelaksanaan:** keterdengaran `/c/` dan `/h/`, batas pelepasan pepet, keakraban kata `oi`, durasi, dan konsistensi ambang masih memerlukan penyamaan penilaian guru serta kalibrasi lapangan. Kelulusan B2 bukan prasyarat membaca C1.'),
  ('C', 1, 'Ketentuan Bersama', '- **Bahan:** tulisan dibuat guru menjelang atau saat asesmen, tanpa kartu, lembar kerja, bahan cetak, atau gambar representasional buatan tangan. Segitiga/persegi sederhana pada C1 L2 diperbolehkan sebagai pembanding nonhuruf; anak tidak diminta menamai bentuknya. Benda dan mainan tidak menampilkan tulisan pemberi jawaban. Semua pilihan tertulis memakai ukuran, warna, ketebalan, dan gaya tulisan yang konsisten.
- **Durasi:** sasaran interaksi sekitar satu menit per indikator, termasuk pengarahan dan pengenalan khusus C2 L2. Persiapan bahan dihitung terpisah. Durasi belum tervalidasi dan bukan batas waktu kelulusan; membaca lebih lambat tidak otomatis dinilai salah.
- **Inventaris:** C1 L3 memakai vokal serta `m n b p`; L4 menambah `s t l k d`; L5 menambah `g r h j c`; L6 boleh memakai inventaris sampai B1 L5, dengan `q/x` bukan bahan utama dekoding; L7 menambah `ng/ny`; L8 menambah `ai/au/oi`. Mulai L4, bahan C2 tidak melampaui C1 setingkat. C1/C2 L5–L6 tanpa `ng/ny/diftong`.
- **Penilaian membaca:** mengeja atau membaca per suku kata diterima apabila akhirnya disatukan menjadi suku kata/kata yang tepat. Nama huruf saja belum memenuhi. Koreksi diri tanpa petunjuk diterima sebelum butir ditutup. Variasi logat dan pelafalan `e` diterima sepanjang identitas kata tetap. Contoh: mengeja lalu menyebut **paku** diterima; membaca **lampu** menjadi **lapu** tidak tepat. Padanan makna tidak menggantikan pembacaan kata pada C1. Kecepatan, irama, dan intonasi tidak diberi skor.
- **Pembacaan kalimat:** setiap kata salah, hilang, atau tambahan dihitung satu kesalahan; dua kata yang bertukar posisi dihitung dua kesalahan posisi. Pengulangan saat mengeja atau mengoreksi diri bukan tambahan. Setelah menyatukan kata, anak tidak diwajibkan mengulang seluruh kalimat. Penerimaan logat pada C1 L8 tetap berdasarkan identitas kata, bukan kewajiban meniru aksen guru.
- **Bantuan guru:** guru tidak membacakan bahan atau memberikan petunjuk jawaban, **kecuali pengenalan label yang ditentukan khusus pada C2 L2**. Pada tahap penilaian C2 L2, pembacaan ulang label oleh guru dilarang. C1 L3–L8 serta C2 L6–L8 tanpa gambar, benda, atau peragaan pemberi konteks jawaban. Tulisan yang sedang diuji tetap terlihat dan boleh dibaca ulang.
- **Respons dan paket:** pertanyaan C2 L6–L8 boleh lisan; jawaban singkat dan padanan makna diterima. Rujukan pertanyaan tetap teks, bukan jawaban salah anak sebelumnya. Gunakan satu paket prapilih, tanpa mengganti butir setelah kesalahan atau mengambil hasil terbaik dari dua paket. Pilihan benda tetap tersedia, tidak disingkirkan atau ditandai setelah ditunjuk.
- **Kosakata:** **buku, bola, susu, mata, kaki, sapi** khusus menjadi bahan C2 L3 dan tidak digunakan sebagai bahan dekoding C1/C2. **Seluruh label C2 L2, baik paket utama maupun cadangan, tidak digunakan sebagai bahan dekoding C1/C2 di level mana pun.** Kata utuh dalam bahan utama, cadangan, dan contoh tidak diulang pada level tepat berikutnya dalam slot yang sama; aturan mengenai tulisan yang dihadapi anak, bukan bahasa instruksi guru. Nama individual C2 L1 diperiksa agar tidak sama dengan label paket C2 L2. Penggunaan benda yang sama bukan otomatis pengulangan kata tertulis.
- **Pelaksanaan tidak sah:** anak belum bersedia, asesmen terputus, tulisan tidak terlihat, atau bahan tidak layak bukan bukti **Belum**. Jangan menggantinya dengan penilaian perilaku atau perubahan kehadiran. Pengenalan label C2 L2 merupakan bagian prosedur yang disetujui, bukan pengajaran bimbel sebelumnya; ketentuan tidak mengajarkan kosakata inti C2 L3 sebelum diagnostik tetap berlaku.'),
  ('C', 2, 'Prosedur C2 L2', '1. **Persiapan:** tetapkan paket, acak urutan tiga label untuk tahap penilaian, dan catat urutan beserta kuncinya sebelum tes. Setiap label ditanyakan sekali. Siapkan tiga pasangan tulisan–benda serta dua benda pengecoh. Semua tulisan memakai huruf kecil dengan gaya yang sama, tanpa warna atau hiasan pembeda.
2. **Pengenalan:** tampilkan ketiga pasangan bersama selama sekitar **15 detik**. Guru menunjuk setiap pasangan dan mengatakan satu kali, **“Tulisan [label] untuk benda ini.”** Alokasikan sekitar lima detik perhatian per pasangan; ketiganya tetap terlihat sepanjang tahap ini. Tidak meminta anak mengulang, tidak memberi latihan memilih, dan tidak mengulang pengenalan berdasarkan respons anak.
3. **Peralihan:** tutup seluruh tulisan pengenalan. Dengan penghalang agar perpindahan tidak dapat diikuti anak, ubah posisi benda. Buka kembali pandangan terhadap **kelima benda**. Tidak ada label yang tetap menempel atau berada di dekat referennya.
4. **Penilaian:** tulis ulang satu label pada tempat netral di papan, berbeda dari lokasi pengenalan, tanpa mengucapkannya. Tanyakan **“Tunjuk benda yang dimaksud tulisan ini.”** Setelah respons ditutup, hapus label dan tulis label berikutnya pada tempat netral yang sama, mengikuti urutan prauji. Bentuk tulisan dipertahankan konsisten; kelima benda tetap tersedia. Tidak memberikan koreksi atau isyarat melalui pandangan, gerak, maupun intonasi.
5. **Skor:** satu penunjukan referen tepat mendapat satu poin; **Lulus bila 3 dari 3 tepat**. Koreksi diri tanpa petunjuk diterima sebelum label diganti. Membaca nyaring tidak diwajibkan. Pada label **air**, menunjuk wadah bening berisi air yang diperkenalkan diterima; anak tidak harus menyentuh air.

**Batas tafsir C2 L2:** Lulus menunjukkan keberhasilan menghubungkan label dengan referennya setelah pengenalan baku pada kesempatan tersebut. Hasil tidak membuktikan keakraban tulisan dari kehidupan anak, kemampuan dekoding, atau ingatan jangka panjang. Ingatan asosiasi dan strategi eliminasi dapat berkontribusi. Belum berarti bukti pada tugas ini belum memenuhi ambang, bukan kesimpulan bahwa anak tidak memahami fungsi tulisan secara umum.'),
  ('C', 3, 'Bahan Cadangan', 'Pilih sebelum penilaian. Jumlah butir, prosedur, dan ambang mengikuti indikator terkait. Contoh urutan pengacakan bukan kewajiban memakai urutan yang sama untuk setiap anak; kunci tetap mengikuti label. Tidak ada paket kedua otomatis setelah gagal.

| Sasaran | Bahan cadangan dan kunci |
|---|---|
| C1 L1–L2 | **L1:** `i o a; u a e; e i o; a u i`; kunci arah tetap, **3 dari 4**. **L2:** isi empat butir tetap, posisi tulisan berturut-turut **2, 3, 1, 3**; kunci **aoi, uie, oau, ioa**, **3 dari 4**. Pembanding tetap angka serta goresan segitiga/persegi, tanpa gambar representasional. |
| C1 L3–L4 | **L3:** **mi; nu; ba; pu**, **3 dari 4**. **L4:** **kuda; siku; apa; ada**, dua KV-KV dan dua V-KV, **3 dari 4**. Kunci pembacaan sesuai tulisan. |
| C1 L5–L6 | **L5:** **ban; karet; pintu; sandal**, struktur berpasangan sama dengan utama, **3 dari 4**. **L6:** **“Budi bawa jas hitam.”**, empat kata; sedikitnya **3 dari 4 kata** tepat, kesalahan paling banyak satu. |
| C1 L7 | **“Penyu datang dari kolam. Monyet pegang pisang besar.”** Delapan kata, seluruhnya berbeda dari utama. `ny`: **penyu, monyet**; `ng`: **datang, pegang, pisang**. Sedikitnya **7 dari 8 kata** tepat, kesalahan paling banyak satu. |
| C1 L8 | **“Konvoi ramai lewat pulau. Tupai kecil pantau kerbau.”** Delapan kata. Sedikitnya **7 dari 8 kata** tepat, kesalahan paling banyak satu, dan sedikitnya satu kata tepat setiap diftong: `ai` → **ramai/tupai**; `au` → **pulau/pantau/kerbau**; `oi` → **konvoi**, yang wajib tepat. |
| C2 L1 | Untuk sasaran **Rani**, susunan dua baris: **Rina / Dodi / Tika**, kemudian **Riki / Rani / Joko**. Dua pengecoh berawal sama: **Rina, Riki**; tiga berawal berbeda: **Dodi, Tika, Joko**. Semua empat huruf. Kunci **Rani, posisi 5**. Ini susunan alternatif, bukan butir tambahan. Untuk anak lain, gunakan nama sasaran sebenarnya beserta pengecoh yang memenuhi aturan. |
| C2 L2 | Label **pot, apel, pena**, dengan pot tanaman plastik polos, apel utuh tanpa stiker, dan pena polos bertutup. Pengecoh **gelas bening kosong dan kain**, tanpa tulisan. Perkenalkan ketiga pasangan bersama sesuai prosedur; urutan penamaan **pot, apel, pena**. Contoh urutan hasil pengacakan penilaian: **pena, pot, apel**; kunci **pena; pot tanaman; apel**. Kelima benda tetap tersedia, guru tidak membacakan ulang label, dan Lulus bila **3 dari 3** tepat. |
| C2 L3–L4 | **L3:** urutan **sapi; kaki; buku; mata; susu; bola**, referen serta pengecoh sama, **5 dari 6**. **L4:** **batu; sapu; kuku; ubi**, seluruh referen nyata; pengecoh botol polos dan gelas. Tiga KV-KV dan satu V-KV; **3 dari 4** memenuhi pembacaan sebelum referen terlihat serta pencocokan. Kata **ubi** juga terdapat pada utama; cadangan ini bukan paket seluruhnya baru setelah latihan utama. |
| C2 L5–L6 | **L5:** **beras; sendok; garam; gula; garpu; gelas**; kunci **bahan; alat; bahan; bahan; alat; alat**, **5 dari 6**. **L6:** **“Lina bawa pita putih.”** Pertanyaan: **“Apa yang dilakukan?” “Apa warna barang itu?” “Barang apa yang disebut?” “Siapa yang diceritakan?”** Kunci **bawa/membawa; putih; pita; Lina**, **3 dari 4**. |
| C2 L7 | **“Nina lari lalu minum. Nina lompat lalu duduk.”** Pertanyaan sama dengan utama; kunci **duduk; lari; minum; lompat**, **3 dari 4**. Kata tindakan sama, tetapi urutannya berbeda. |
| C2 L8 | **“Sebab petir, Rudi takut. Tika kesal sebab bising.”** Prosedur dan pertanyaan sama dengan utama; kunci **Rudi takut; petir; bising/suara gaduh; Tika kesal/jengkel**, **3 dari 4**. |

Pada semua paket C2 L2, guru memeriksa benda aktual agar tidak memuat angka, huruf, merek, atau stiker.'),
  ('C', 4, 'Catatan Risiko', '- **C2 L1:** peluang **1/6** hanya berlaku pada model tebakan acak merata atas enam pilihan, bukan peluang kelulusan kebetulan yang sudah terukur. Pengetahuan huruf awal dapat mempersempit pilihan menjadi tiga. Kesulitan pengecoh dan kebutuhan memindai enam nama masih perlu dikalibrasi.
- **C2 L2:** tiga label, pengenalan sekitar 15 detik, serta ambang 3 dari 3 belum tervalidasi lapangan. Semua label harus tepat, sehingga satu kesalahan menggagalkan indikator; ketentuan ini tidak diterapkan sebagai standar umum Alur C. Lima benda dan tidak menghilangkan pilihan mengurangi sebagian petunjuk, tetapi anak dapat mengabaikan benda yang tidak diperkenalkan dan menyimpulkan pasangan ketiga dari dua pasangan yang diketahui.
- **Progresi:** L1 menguji satu identitas; L2 memperluas hubungan ke tiga label dengan pengenalan baku; L3 memakai enam kata inti tanpa pengenalan sebelum diagnostik. Urutan kesulitan aktual tidak dapat disimpulkan dari jumlah pilihan atau persentase benar saja.
- **C2 L4:** empat kata memperpendek tugas, tetapi kelayakan sekitar satu menit dan ambang 3 dari 4 perlu diuji langsung. Pembacaan sebelum referen dibuka mengurangi tebakan berbasis benda, bukan membuktikan bahwa kata belum dikenal atau memastikan proses dekoding tertentu.
- **Kalibrasi keseluruhan:** durasi C2 L2/L4, kelayakan mainan sebagai referen, variasi logat, dan konsistensi skor membaca tetap perlu diperiksa. Empat jawaban C2 L6–L8 berasal dari satu teks masing-masing, bukan empat bacaan independen.'),
  ('D', 1, 'Ketentuan Bersama', '- **Status dan konstruk:** D1 mengukur reproduksi dengan model visual yang tetap terlihat; D2 mengukur produksi tanpa model visual. Anak tidak wajib membaca atau menamai model D1. Perilaku dan kepatuhan tidak diberi skor.
- **Pelaksanaan:** pada D1, anak menulis di ruang kosong, bukan menebalkan atau menjiplak. Pada D2, tutup model, label pemberi jawaban, dan tulisan dari tugas sebelumnya. Guru tidak menulis jawaban, mengeja, membentuk huruf di udara, atau mengarahkan tangan anak. Koreksi diri berupa menghapus atau menulis ulang diperbolehkan sebelum jawaban ditutup; nilai hasil akhir tanpa petunjuk koreksi guru.
- **Bahan:** pensil dan kertas polos; kertas dengan garis cetak tidak digunakan. Guru boleh menggoreskan garis dasar sederhana mulai D1 L3 dan D2 L2, tanpa kotak per huruf, titik awal, atau penanda spasi. D1 L1–L2 dan D2 L1 memakai kertas tanpa garis. Model dibuat guru menjelang atau saat asesmen. Tidak menggunakan kartu, lembar kerja, stensil, atau gambar representasional; bentuk geometris pramenulis diperbolehkan.
- **Waktu:** sasaran interaksi sekitar satu menit per indikator, belum tervalidasi; persiapan dihitung terpisah. Melewati satu menit bukan alasan otomatis memberi Belum. Genggaman, tangan dominan, kecepatan, dan frekuensi melihat kembali model tidak dinilai. Sediakan ruang menulis yang cukup.
- **Inventaris:** D1 L1–L2 memakai garis/bentuk, bukan inventaris huruf. D2 L1 memakai garis/bentuk; D2 L2 memakai inisial nama sebenarnya, tidak dibatasi inventaris B1 L2. Untuk D1 dan D2 mulai L3, batas kumulatifnya: **L3:** a i u e o m n b p s t l k d; **L4:** tambahan g r h j c; **L5:** tambahan w y f z v q x; **L6:** tambahan ng/ny; **L7:** tambahan ai/au/oi; **L8:** inventaris sama dengan L7. Inventaris adalah batas bahan, bukan kewajiban memasukkan semuanya. Struktur unit mengikuti tabel; D2 L7 memakai struktur kata L4–L6. D2 L8 tidak mewajibkan penggunaan grafem kompleks.
- **Kosakata:** `buku, bola, susu, mata, kaki, sapi` serta label `lap, air, roti, pot, apel, pena` boleh digunakan pada Alur D, termasuk dikte. Pengecualian pada Alur C melindungi penafsiran tugas dekoding; bukan larangan lintas alur. Namun, kata-kata tersebut maupun kata yang sebelumnya dibaca, misalnya `kapas`, dapat terbantu ingatan ejaan. Dikte membuktikan penulisan tanpa model, bukan strategi encoding tertentu. Tidak ada pengajaran jawaban sebelum diagnostik.
- **Paket dan kesempatan:** pilih satu paket sebelum tes; jangan mengganti butir setelah salah, menggabungkan skor, atau mengambil hasil terbaik dari dua paket. Kata utuh yang diberikan kepada anak dalam paket utama, cadangan, dan contoh tidak diulang pada level tepat berikutnya dalam slot yang sama; pengecualian tidak diperlukan untuk huruf/suku kata penyusun atau kata spontan anak pada D2 L8. Contoh kalibrasi khusus guru tidak dibacakan kepada anak. Asesmen tidak terlaksana, terputus, atau anak belum bersedia bukan bukti Belum dan tidak diganti dengan perubahan kehadiran.'),
  ('D', 2, 'Rubrik Tulisan', '- **Huruf dikenali:** bagian pembeda dan orientasinya tampak, tanpa meminta anak menamai huruf untuk menyelamatkan bentuk yang ambigu. Contoh pembeda: dua lengkungan `m` dibanding satu pada `n`; titik `i/j`; garis silang `t`; letak batang dan badan `b/d/p/q`; bagian pembeda `a/o` dan `e/c`. Bentuk konvensional alternatif `a/g` diterima. Ukuran, ketebalan, kemiringan umum, dan penampilan tidak dinilai selama identitas huruf tetap dapat ditentukan. Huruf cermin atau `b` yang menjadi `d` adalah kesalahan.
- **Kapital dan titik:** pada D1, kapital/kecil mengikuti model; ketidaksesuaian dihitung sebagai kesalahan huruf. Pada D1 L7–L8, titik akhir juga bagian model. Pada D2, kapital/kecil diterima sebagai huruf yang sama; kapital awal dan titik akhir tidak menentukan kelulusan. Ini membedakan kesetiaan menyalin dari kemampuan menerapkan konvensi kalimat.
- **Hitungan kesalahan:** satu huruf hilang, ditambahkan, diganti, atau tidak dikenali dihitung satu kesalahan; satu huruf bermasalah tidak dihitung berulang karena beberapa cacat. Pertukaran urutan dua huruf dihitung dua. Penghilangan tidak menyebabkan seluruh huruf sesudahnya dianggap salah: `baju → bau` satu kesalahan; `baju → bauj` dua. Titik pada `i/j` termasuk bentuk huruf, bukan tanda baca terpisah. Kesalahan spasi diperiksa tersendiri.
- **Spasi D1 L6–L8 dan D2 L7–L8:** batas kata terpenuhi bila celahnya kira-kira selebar satu `o` anak atau lebih, dan tidak ada celah di dalam kata yang selebar itu. Gunakan ukuran huruf yang lazim pada sampel, bukan huruf terbesar. Bila tidak ada `o`, taksir dari badan bulat `a/b/d` atau bentuk kapital yang tersedia, tanpa tugas tambahan. Diterima: `topi [celah selebar o] baru`; ditolak: `topibaru` atau `to [celah selebar o] pi baru`. Keterangan dalam kurung siku hanya untuk guru. Perpindahan baris tepat pada batas kata diterima; sediakan ruang agar anak tidak perlu memotong kata.
- **Bunyi dan dikte:** stimulus dibacakan wajar, tanpa mengeja, memisahkan suku kata, atau memperpanjang bunyi pemberi petunjuk. Satu pengulangan utuh diperbolehkan atas permintaan anak, termasuk seluruh kalimat D2 L7. Anak boleh mengeja sendiri. Pada D2 L3 gunakan fonem, bukan nama huruf; pelepasan pepet sangat lemah pada `/b/` ditoleransi, bukan “be” atau suku kata penuh. Bunyi pepet dan taling sama-sama ditulis `e`; tanda pembeda pelafalan tidak diwajibkan. Sinonim tidak menggantikan kata dikte.
- **Khusus D2 L8:** konstruk utama ialah menghasilkan satu kalimat tertulis dari gagasan sendiri, bukan daftar kata. Syarat minimum: sedikitnya tiga kata, subjek tertulis dan predikat yang menyatakan tindakan/keadaan tentang subjek, pemisahan kata terpenuhi, serta paling banyak satu kesalahan huruf pada setiap kata. Setiap suku kata harus tetap terwakili berurutan, termasuk inti vokalnya; hilangnya satu konsonan tidak otomatis berarti seluruh suku kata hilang. Tidak ada batas atas empat kata; nilai seluruh kalimat, bukan tiga atau empat kata terbaik. Guru tidak menuntut pemanjangan kalimat. Kreativitas, kebaruan gagasan, dan pilihan ragam percakapan tidak dinilai.'),
  ('D', 3, 'Rubrik Pramenulis', '- **Garis:** tegak berarah utama atas–bawah dengan ujung kurang lebih sejajar vertikal; mendatar berarah utama kiri–kanan dengan ujung kurang lebih setinggi; miring memperlihatkan perpindahan ke samping sekaligus naik/turun yang jelas. Sedikit goyangan diterima. Contoh: garis tegak agak bergelombang diterima untuk sasaran tegak; garis mendatar tidak. Arah gerakan pensil tidak dinilai. Lengkung berupa satu busur terbuka; arah buka mengikuti model D1, bukan lingkaran atau zigzag.
- **Bentuk:** silang mempunyai empat lengan yang bertemu pada satu perpotongan; siku mempunyai dua garis tegak–mendatar yang bertemu pada ujung; lingkaran merupakan putaran tanpa sudut dan boleh oval; segi empat mempunyai empat sisi dan empat sudut. Contoh diterima: silang dengan panjang lengan berbeda atau lingkaran oval. Contoh ditolak: bentuk `T` untuk silang, busur terbuka lebar untuk lingkaran, atau tiga sisi untuk segi empat.
- **Pertemuan dan penutupan:** celah kecil pada titik pertemuan atau penutupan diterima jika tidak lebih lebar daripada ujung grafit pensil yang digunakan anak, bukan lebar batang pensil. Model disiapkan sekitar 2–3 cm agar terlihat; ukuran hasil anak tidak harus sama. Guru menilai sekilas terlebih dahulu; bila ragu, pemeriksaan dengan ujung pensil atau bantuan penggaris dilakukan setelah anak selesai, tanpa mengembalikan rasio atau batas milimeter sebagai syarat wajib.'),
  ('D', 4, 'D2: Tanpa Model', '### Kalibrasi D2 L8

Contoh berikut khusus untuk guru. Anggap bentuk huruf dan spasinya memenuhi rubrik kecuali disebut berbeda. Kata yang dimaksud mengacu pada gagasan anak, bukan tebakan guru; klarifikasi lisan netral tidak boleh digunakan untuk menganggap huruf atau kata yang tidak tertulis sebagai sudah tertulis.

- **Lulus:** `Aku suka roti` dan `Bola itu biru.` Keduanya tiga kata dengan subjek dan predikat; predikat tidak harus kata kerja. Ketiadaan titik pada contoh pertama tidak menggagalkan.
- **Lulus, kosakata lebih sulit:** tulisan `Aku suga helikobter berwarna merah.` untuk gagasan `Aku suka helikopter berwarna merah.` Kata `suga` mempunyai satu penggantian huruf, demikian pula `helikobter`; setiap kata masih mempertahankan suku katanya. Lima kata dan dua kesalahan yang tersebar pada dua kata tidak otomatis menggagalkan.
- **Belum, suku kata hilang:** `Aku suka bi.` untuk gagasan `Aku suka ubi.` Penghilangan `u` memang hanya satu kesalahan huruf, tetapi menghilangkan satu suku kata utuh pada `u-bi`. Pemeriksaan contoh `u-bi` dan `he-li-kop-ter` menerapkan [kaidah pemenggalan EYD](https://ejaan.kemendikdasmen.go.id/eyd/penulisan-kata/pemenggalan-kata/); ambang lulus tetap merupakan rubrik operasional kurikulum, bukan ketentuan EYD.
- **Belum, alasan lain:** `roti bola baju` hanya daftar kata; `Aku sk roti` untuk `Aku suka roti` kehilangan dua huruf pada satu kata; `Akusuka roti` tidak mempertahankan batas kata. Penjelasan lisan anak tidak menggantikan unsur tertulis yang tidak memenuhi.'),
  ('D', 5, 'Bahan Cadangan', 'Pilih sebelum tes; bukan kesempatan tambahan setelah gagal. Jumlah butir, cara penyajian, inventaris, dan ambang mengikuti indikator utama. Pengelompokan baris di bawah hanya untuk meringkas dokumen, bukan menggabungkan indikator.

| Level | Cadangan D1 | Cadangan D2 |
|---|---|---|
| L1–L2 | **L1:** mendatar; lengkung terbuka ke kiri; tegak; miring naik ke kiri. Kunci sesuai model, 3 dari 4. **L2:** segi empat; siku; lingkaran; silang. Kunci sesuai ciri bentuk, 3 dari 4, dengan toleransi penutupan yang sama. | **L1:** instruksi lingkaran; miring; mendatar; tegak, tanpa model; 3 dari 4. **L2:** tidak mengganti nama atau inisial; tetap nama yang telah ditetapkan, dengan kunci huruf pertamanya. |
| L3–L4 | **L3:** n; d; a; t, kunci sama, 3 dari 4. **L4:** ni; sa; ko; bu, kunci sama, 3 dari 4 KV tepat seluruhnya. | **L3:** /u/; /n/; /t/; /p/, kunci u; n; t; p, 3 dari 4. **L4:** mi; tu; ba; se, kunci sama, 3 dari 4; `se` diucapkan dengan pepet, tanpa memberi contoh kata pembawa. |
| L5–L6 | **L5:** roda; dasi, delapan huruf, maksimal satu kesalahan keseluruhan. **L6:** baju biru, delapan huruf, maksimal satu kesalahan dan satu batas kata tepat. | **L5:** pita; madu, delapan huruf, maksimal satu kesalahan keseluruhan. **L6:** beras; tikus, sepuluh huruf, maksimal satu kesalahan keseluruhan; kedua konsonan akhir tidak boleh sama-sama hilang. |
| L7–L8 | **L7:** “Dodi baca peta.”, model dekat. **L8:** “Tono beli bola.”, model papan. Masing-masing tiga kata dan 12 huruf; maksimal satu kesalahan gabungan huruf/kapital/titik dan dua batas kata tepat. | **L7:** “Siti makan sup.”, tiga kata, 12 huruf; maksimal satu kesalahan huruf dan dua batas kata tepat, dengan aturan pengulangan utuh yang sama. **L8:** tidak menyediakan kalimat cadangan dari guru; gagasan tetap milik anak. Revisi mandiri sebelum selesai merupakan bagian satu sampel, bukan pemilihan hasil terbaik. |'),
  ('D', 6, 'Catatan Risiko', '- **Durasi dan ingatan:** seluruh sasaran waktu masih perlu diuji. Khusus D2 L7, satu pengulangan utuh mungkin belum mencukupi anak yang memerlukan waktu lebih lama untuk menulis 12 huruf; aturan dipertahankan untuk pengamatan lapangan, tanpa menambah dikte per kata.
- **Kesepakatan penilaian:** patokan spasi, penutupan bentuk dengan ujung pensil, huruf ambigu, dan keterwakilan suku kata perlu dikalibrasi memakai sampel tulisan nyata. Ambang ini belum dinyatakan tervalidasi antarpenilai.
- **D2 L8:** toleransi per kata mengurangi penalti panjang kalimat, tetapi tidak menyetarakan seluruh kosakata pilihan anak. Pantau apakah syarat ejaan masih terlalu menentukan dibanding kemampuan menghasilkan kalimat. Toleransi ejaan per kata pada L8 sengaja lebih longgar daripada toleransi keseluruhan D2 L7 karena konstruk L8 adalah menyusun kalimat sendiri.'),
  ('E', 1, 'Ketentuan Bersama', '- **Cakupan:** plafon bilangan 20. E1 mengukur urutan, lambang, posisi, dan relasi bilangan. E2 mengukur kuantitas serta struktur dengan total tetap. Perpindahan benda antarkelompok pada E2 tidak menambah atau mengurangi keseluruhan benda.
- **Bahan:** tulisan dibuat guru menjelang atau saat asesmen, tanpa kartu, lembar kerja, bahan cetak, kalender, penggaris bertanda angka, atau gambar representasional. Paket ini tidak memakai dadu, termasuk dadu polos/berlubang. Gunakan benda polos yang seragam dalam setiap kumpulan, mudah ditangani, tidak tajam, dan tidak mudah menggelinding, misalnya balok kayu polos. Seluruh benda harus terlihat dan tidak bertumpuk. Guru memeriksa jumlah tanpa memperdengarkan hitungannya kepada anak.
- **Respons:** bentuk utama ialah menyebut, menunjuk, atau menyusun benda sesuai tabel. Tidak ada kewajiban menulis angka. Pada pengisian simbolik, guru mencatat jawaban setelah anak menetapkannya, tanpa pembetulan. Tulisan angka spontan anak boleh diterima jika nilainya jelas; kerapian tidak dinilai. Jika bentuknya ambigu, minta klarifikasi nilai secara netral, bukan memberi contoh angka.
- **Bahasa bilangan:** sebutan Indonesia maupun padanan daerah yang diketahui maknanya diterima. Guru menetapkan padanan yang dipahami sebelum tes; logat dan artikulasi tidak dinilai selama nilai bilangan jelas. Menyebut digit terpisah, misalnya “satu, dua”, belum merupakan sebutan jumlah dua belas. Ketidakpahaman guru terhadap bahasa respons tidak otomatis menjadi bukti jawaban salah.
- **Koreksi dan gangguan:** koreksi diri serta menghitung ulang secara mandiri diterima sebelum butir ditutup. Guru tidak mengatakan “coba hitung lagi” berdasarkan kesalahan anak. Instruksi boleh diulang utuh satu kali atas permintaan, tanpa petunjuk tambahan. Jika benda tercecer, tersembunyi, atau susunan terganggu sehingga proses tidak dapat dinilai, pulihkan bahan dan ulangi butir tanpa koreksi jawaban. Menghitung benda yang sama dua kali ketika seluruh bahan tetap terlihat merupakan kesalahan hitung, bukan otomatis gangguan pelaksanaan.
- **Waktu dan paket:** sasaran interaksi sekitar satu menit, belum tervalidasi dan bukan batas waktu kelulusan. Persiapan dicatat terpisah; penataan ulang di tengah tes tetap dicatat sebagai beban pelaksanaan. Gunakan satu paket prapilih, tanpa mengganti butir setelah salah atau mengambil hasil terbaik dari dua paket. Diagnostik tidak didahului latihan jawaban paket dan tidak mensyaratkan pernah mengikuti pengajaran bimbel. Anak belum bersedia atau asesmen terputus bukan bukti Belum; perilaku dan kehadiran tidak menggantikan hasil akademik.
- **Pilihan tertulis:** ukuran, warna, dan gaya angka konsisten. Pada E1 L2/L3/L5, katakan sekali, “Angka yang sama boleh kamu tunjuk lagi.” Semua pilihan tetap tersedia, tanpa dicoret atau ditandai. Sasaran diulang tanpa pola tetap; guru tidak mengumumkan bahwa semua pilihan sasaran akan ditanyakan. Benda hitung tidak disediakan pada E1 serta E2 L7–L8; strategi jari spontan anak diperbolehkan.
- **Menghitung dan kardinalitas:** E2 L1 wajib memperlihatkan satu benda–satu hitungan melalui menunjuk, menyentuh, atau memindahkan benda sambil membilang, lalu menyebut jumlah keseluruhan. Jawaban langsung yang benar belum cukup membuktikan korespondensi tersebut. Pada E2 L2–L3, menghitung dengan menunjuk tidak wajib; jawaban langsung atau hitung dalam hati diterima, tetapi tidak otomatis ditafsirkan sebagai subitisasi. Jika anak menghitung, sebutan jumlah akhirnya harus sesuai banyak benda. Pembedaan urutan lisan, korespondensi, dan kardinalitas sejalan dengan [panduan IES](https://ies.ed.gov/use-work/resource-library/resource/other-resource/teaching-math-young-children-families-and-caregivers); paket dan ambang di sini merupakan rancangan internal, bukan norma usia dari sumber tersebut.
- **Pembagian E2 L4–L5:** pembagian bebas, tetapi kedua bagian harus berisi benda. Semua benda digunakan, tanpa tambahan atau benda yang dikeluarkan dari keseluruhan. Anak menyebut banyak benda pada masing-masing bagian. Tidak wajib membagi sama banyak atau menemukan beberapa cara. Menyisihkan satu benda sebagai bagian pertama lalu menghitung bagian lainnya sah. Lulus menunjukkan kemampuan membentuk dan menyebut dua bagian dengan total tetap, bukan bukti penguasaan pasangan bilangan atau fleksibilitas dekomposisi.
- **Pengulangan bahan (keputusan final pemilik):** bahan dalam paket utama, cadangan, dan contoh tidak digunakan kembali sebagai butir utuh yang identik pada level tepat sesudahnya dalam slot yang sama. Butir utuh mencakup tugas beserta bilangan, pasangan, atau susunannya. Nilai bilangan individual boleh digunakan kembali dalam tugas berbeda; misalnya, mengenali `14` berbeda dari membandingkan pasangan `14–17`. Aturan ini tidak membuka izin melatih jawaban sebelum diagnostik.'),
  ('E', 2, 'Penyiapan Khusus', '- **Susunan benda:** kode R berarti baris renggang; S sebaran rapat tidak beraturan tanpa tumpang tindih; M baris melengkung renggang. Kode hanya untuk guru, tidak ditulis pada bahan. Jangan membentuk pola titik dadu. Variasikan posisi kumpulan; jumlah tidak selalu bertambah bersama luas sebarannya. Hanya kumpulan untuk butir yang sedang diuji diperlihatkan.
- **Garis bilangan E1 L7:** guru menggoreskan garis mendatar dengan 21 takik dan 20 ruas berjarak sama. Hanya takik bernilai 0, 10, dan 20 diberi label. Gunakan tepi lurus polos dan potongan kertas sebagai pembanding jarak saat persiapan. Periksa seluruh takik sebelum tes. Anak menunjuk takik, bukan menulis angka; target tidak diberi label pada garis. Menghitung takik secara mandiri diperbolehkan.
- **Kasus 20 (penjelasan untuk guru):** pada E2 L6, `20` dapat ditata sebagai sepuluh benda dalam satu wadah dan sepuluh benda di luarnya. Pada L7, bentuknya `20 = 10 + 10`. Ini bukan pernyataan bahwa digit satuan pada 20 bernilai sepuluh. Pada L8, digit `2` bernilai 20, sedangkan digit `0` bernilai 0. Penjelasan ini tidak dibacakan sebagai pengajaran sebelum tes.
- **Perintah baku E2 L7:** gunakan hanya **“Isi bagian yang kosong supaya kedua sisi sama.”** Anak menyebut bilangan pengisi. Dilarang menambah contoh, menjelaskan tanda atau konsep, membacakan bilangan sasaran, atau menguraikan jawabannya menjadi langkah-langkah. Bila diminta mengulang, ulangi kalimat yang sama, paling banyak satu kali sesuai ketentuan bersama. Berlaku untuk utama dan cadangan.'),
  ('E', 3, 'E1: Urutan dan Lambang', 'E1 L7→L8 adalah perpindahan subkemampuan yang disengaja, dari posisi pada garis bilangan menuju hitung loncat. Urutan 11–20 tidak dijadikan milestone tambahan; digunakan secara fungsional pada L7. L8 tidak menguji penemuan aturan pola karena langkah dua sudah dinyatakan.'),
  ('E', 4, 'E2: Kuantitas dan Struktur', '**Batas tafsir E2 L6:** Lulus menunjukkan keberhasilan menata tiga total sampel sebagai satu kelompok sepuluh beserta sisanya, bukan pemeriksaan seluruh bilangan 11–20 atau bukti otomatis penguasaan nilai digit. Ambang 3 dari 3 dipilih bersama pengurangan jumlah butir; tidak menoleransi satu butir salah dan belum dinyatakan setara secara pengukuran dengan ambang sebelumnya.

**Catatan untuk guru:** tanda `+` pada kunci E2 L4–L6 hanya ringkasan, bukan tulisan yang wajib dibaca anak. Pada L7, bentuk `10+n` menyatakan struktur total yang sudah diketahui; pada L8, yang ditanyakan ialah nilai satu digit menurut posisinya. Catatan ini tidak dibacakan sebagai tambahan penjelasan pada E2 L7.'),
  ('E', 5, 'Bahan Cadangan', 'Pilih sebelum asesmen; jumlah butir dan ambang mengikuti indikator terkait. Cadangan bukan paket kedua otomatis. Pada tugas konkret, ganti susunan awal dan posisi kumpulan, tetapi pertahankan jumlah serta prosedur yang ditetapkan.

| Level | Cadangan E1 | Cadangan E2 |
|---|---|---|
| L1 | Tidak ada urutan alternatif: sasaran tetap 1, 2, 3, 4, 5, satu rangkaian mandiri dengan rubrik yang sama. | 3-R; 2-M; 1 di sisi kiri; 3-S. Kunci 3; 2; 1; 3; korespondensi wajib; 3 dari 4. |
| L2 | Pilihan 5 2 4 1 3; sebut 2; 5; 3; 1; 3; 4. Kunci mengikuti sebutan; 5 dari 6. | 5-R; 4-S; 4-M; 5-S. Kunci 5; 4; 4; 5; 3 dari 4. |
| L3 | Pilihan 7 10 8 3 9 6; sebut 10; 7; 9; 6; 9; 8. `3` pengecoh. Kunci mengikuti sebutan; 5 dari 6. | 9-M; 7-R; 8-S; 10-R; 6-M. Kunci 9; 7; 8; 10; 6; 4 dari 5. |
| L4 | 1: sebelum; 6: sesudah; 8: sebelum; 3: sesudah. Kunci 0; 7; 7; 4; 3 dari 4. | Total 3; 5; 2; 4, dengan susunan awal berbeda dari utama. Semua pembagian pada kunci L4 diterima; 3 dari 4. |
| L5 | Pilihan tiga baris 13 18 10 16 / 20 11 15 19 / 12 17 9 14; sebut 18; 12; 20; 15; 11; 17; 19; 13; 16; 12; 14. Kunci mengikuti sebutan; 10 dari 11. | Total 9; 6; 10; 8; 3 dari 4. Kunci 6/10/8 mengikuti utama; 9: 1+8, 2+7, 3+6, 4+5, termasuk urutan terbalik. |
| L6 | Pasangan 20–15; 13–16; 12–20; 9–8; 19–11; 0–7. Kunci 20; 16; 20; 9; 19; 7; 5 dari 6. | Tiga total 12; 15; 20. Kunci sepuluh dalam wadah dengan sisa 2; 5; 10, seluruh benda dipertahankan; 3 dari 3. Batas tafsir tiga sampel mengikuti utama. |
| L7 | Garis dengan ketentuan sama; target 14; 4; 18; 9. Kunci takik yang berjarak 14; 4; 18; 9 langkah dari 0; 3 dari 4. | 19 = 10 + …; 12 = 10 + …; 20 = 10 + …; 15 = 10 + …. Perintah baku sama, tanpa tambahan penjelasan. Kunci 9; 2; 10; 5; 3 dari 4 dan butir 20 wajib tepat. |
| L8 | 5,7,9,…,… → 11–13; 8,10,12,…,… → 14–16; 10,12,14,…,… → 16–18; 11,13,15,…,… → 17–19. 3 dari 4 baris tepat kedua lanjutannya. Dua baris genap dan dua ganjil; tidak ada baris identik dengan utama. | 17: digit 7; 20: digit 0; 11: digit 1 kanan; 18: digit 1; 20: digit 2. Kunci 7; 0; 1; 10; 20; 4 dari 5. |'),
  ('E', 6, 'Catatan Risiko', '- **Durasi E2 L6:** pengurangan menjadi tiga butir mengurangi bahan dan satu putaran tugas, tetapi belum memastikan selesai sekitar satu menit. Catat waktu pengarahan, penataan, penghitungan, dan respons. Jangan mengganti proses anak dengan kelompok sepuluh siap pakai demi mengejar waktu.
- **Ambang dan sampel:** E2 L6 kini menuntut tiga butir tepat; satu kesalahan pada butir yang terlaksana sah membuat ambang tidak tercapai. Pengaruh kesalahan sesaat dan kesetaraan utama/cadangan perlu dikalibrasi. Kelulusan tidak membuktikan setiap nilai dalam rentang telah diuji.
- **Bahasa dan simbol E2 L7:** pemahaman perintah “kedua sisi sama” serta notasi simbolik dapat memengaruhi hasil. Hasil menunjukkan kemampuan melengkapi bentuk yang diberikan tanpa pengajaran tambahan, bukan bukti strategi mental tertentu atau kemampuan menulis notasi sendiri. Guru tidak mengatasi kesulitan saat tes dengan penjelasan konsep.
- **Batas pembagian:** strategi satu benda dan sisanya tetap sah pada E2 L4–L5. Jangan menafsirkan kelulusan sebagai penguasaan seluruh pasangan bilangan atau fleksibilitas beberapa cara, dan jangan menambahkan syarat variasi pembagian secara lokal.
- **Kalibrasi keseluruhan:** durasi E1 L5 serta E2 L3–L5, penilaian gangguan benda, dan kesepakatan terhadap respons bilangan masih memerlukan pengamatan lapangan. Cadangan E1 L8 tetap dalam plafon 20, tetapi tidak meminta jawaban 20 secara langsung; paket utama memintanya. Kesetaraan paket tidak disimpulkan hanya dari jumlah soal atau persentase benar.'),
  ('F', 1, 'Ketentuan Bersama', '- Plafon bilangan adalah 20. F1 mengukur matematika non-operasi sesuai subdomain per level; F2 mengukur operasi/peristiwa yang mengubah jumlah.
- Sasaran interaksi sekitar satu menit per indikator; persiapan bahan dicatat terpisah. Durasi belum tervalidasi dan bukan batas waktu kelulusan.
- Tanpa bahan cetak, kartu angka, dadu cetak, penggaris bertanda angka, atau gambar representasional. Tulisan angka dan simbol dibuat guru saat itu atau menjelang asesmen.
- Gunakan satu paket penilaian yang dipilih sebelum tes. Jangan mengganti butir setelah anak salah, mencampur skor paket utama-cadangan, atau mengambil hasil terbaik dari dua paket. **Satu-satunya pengecualian** adalah penggantian butir F2 L1–L4 karena isi penutup terlihat (lihat di bawah).
- Koreksi diri tanpa petunjuk diterima sebelum butir ditutup. Guru tidak memberi koreksi, isyarat jawaban, atau penjelasan konsep saat tes.
- Jika benda jatuh, bergeser, tertutup, atau susunan terganggu sehingga butir tidak dapat dinilai, pulihkan bahan dan ulangi butir tanpa koreksi jawaban. Jika anak belum bersedia atau asesmen terputus, kesempatan tersebut bukan bukti **Belum**.
- Respons dapat berupa menyebut, menunjuk, menyusun, atau meletakkan benda sesuai tabel. Tulisan angka anak tidak diwajibkan; kerapian tidak dinilai.
- Sebutan bilangan Indonesia maupun padanan daerah diterima bila nilainya jelas bagi guru, mengikuti ketentuan Alur E.
- **F2 L1–L4 memakai benda tertutup.** Guru memperlihatkan dan menyebut jumlah awal, menutup kelompok, melakukan perubahan secara terlihat, lalu menanyakan jumlah sekarang tanpa membuka penutup. Jari anak boleh dipakai.
- Pada F2 L1–L4, setelah jawaban dicatat, guru membuka penutup hanya untuk membereskan atau menyiapkan butir berikutnya, tanpa menyebut benar/salah, tanpa membetulkan, dan tanpa meminta anak melihat hasil sebagai koreksi.
- Jika anak mengintip atau membuka penutup sebelum jawaban final sehingga isi terlihat, butir tidak sah dan diganti dengan butir cadangan setara yang belum dipakai; bila gangguan berulang, asesmen indikator dicatat belum terlaksana. Jika penutup tersentuh tetapi isi tidak terlihat, guru menata ulang dan melanjutkan tanpa memberi skor perilaku.
- Pada F2 L5–L6, sepuluh benda penopang selalu tersedia di sisi meja, tidak dikelompokkan dan tidak diperagakan guru. Anak boleh memakai atau tidak memakai. Pada F2 L7–L8, benda hitung tidak disediakan; jari anak sendiri diperbolehkan.
- Pada F1 L8, benda target tidak boleh sama dengan benda target F1 L7 utama maupun cadangan. Satuan contoh diletakkan terpisah dari target, boleh dilihat, tetapi tidak boleh dipegang atau dipindahkan anak sebelum menyatakan perkiraan.
- **Batas tafsir F2 L1–L4:** Lulus menunjukkan anak dapat menentukan jumlah akhir dari jumlah awal dan perubahan yang diamati ketika kumpulan akhir tidak terlihat. Hasil belum membuktikan strategi mental tertentu.
- Butir utuh dalam paket utama, cadangan, dan contoh tidak digunakan kembali pada level tepat sesudahnya dalam slot yang sama.'),
  ('F', 2, 'Bahan Cadangan', 'Pilih paket cadangan sebelum asesmen sebagai pengganti paket utama, bukan kesempatan tambahan setelah gagal. Jumlah butir, prosedur, ambang, dan batas tafsir tetap mengikuti indikator terkait. Penggantian butir karena gangguan penutup pada F2 L1–L4 adalah penanganan pelaksanaan tidak sah, bukan kesempatan kedua setelah jawaban salah.

| Sasaran | Bahan cadangan dan kunci |
|---|---|
| F1 L1 | Set 1: empat balok sama bentuk dan ukuran, hanya warna berbeda, **2 kuning dan 2 hijau**; kunci kelompok kuning dan hijau. Set 2: empat balok sama bentuk dan warna, hanya ukuran berbeda, **2 besar dan 2 kecil**; kunci kelompok besar dan kecil. Lulus **2 dari 2 set**. |
| F1 L2 | Enam butir goresan polos dengan prosedur sama. **B1:** lingkaran, persegi panjang, segitiga, persegi; tanya segitiga, kunci posisi 3. **B2:** persegi, lingkaran, persegi panjang, segitiga; tanya persegi panjang, kunci 3. **B3:** segitiga, persegi, lingkaran, persegi panjang; tanya persegi, kunci 2. **B4:** persegi panjang, lingkaran, persegi, segitiga; tanya lingkaran, kunci 2. **B5:** lingkaran, persegi panjang, persegi, segitiga; tanya persegi panjang, kunci 2. **B6:** persegi, segitiga, persegi panjang, lingkaran; tanya persegi, kunci 1. |
| F1 L3 | Pola AB cadangan: **biru-kuning; merah-putih; hijau-hitam; kuning-merah**, masing-masing diulang 3 kali. Anak melanjutkan dua benda; ambang **3 dari 4**. |
| F1 L4 | Pola ABC cadangan: **kuning-hijau-biru; putih-merah-hitam; hijau-kuning-merah; biru-putih-hijau**, masing-masing diulang 3 kali. Anak melanjutkan tiga benda; ambang **3 dari 4**. |
| F1 L5 | Pasangan atas-bawah cadangan: **13-9; 7-12; 10-15; 16-11 cm**. Kunci benda lebih panjang: **atas; bawah; bawah; atas**. |
| F1 L6 | Tiga set cadangan, masing-masing tiga benda: kira-kira **5, 9, 13 cm**; **7, 10, 14 cm**; **6, 11, 16 cm**. Kunci tiap set tetap terpendek-sedang-terpanjang; ambang **2 dari 3**. |
| F1 L7 | Target cadangan berupa strip mika polos sepanjang **3 satuan; 5 satuan; 7 satuan**. Kunci **3; 5; 7**; aturan celah/tumpang tindih dan kelayakan bahan sama. |
| F1 L8 | Target cadangan bukan target F1 L7: tiga sedotan polos lurus sepanjang **6 satuan; 9 satuan; 12 satuan**. Toleransi ±20% dibulatkan: **6 = 5-7; 9 = 7-11; 12 = 10-14**. Anak tetap menyebut perkiraan sebelum satuan ditempelkan; satuan contoh tidak boleh dipegang anak. |
| F2 L1 | Dengan benda tertutup: **2 tambah 1; 1 tambah 1; 2 tambah 1; 1 tambah 1**. Kunci **3; 2; 3; 2**. |
| F2 L2 | Dengan benda tertutup: **4 ambil 1; 2 ambil 1; 5 ambil 1; 3 ambil 1**. Kunci **3; 1; 4; 2**. |
| F2 L3 | Dengan benda tertutup: **1 dan 2; 2 dan 2; 1 dan 3; 2 dan 3**. Kunci **3; 4; 4; 5**. |
| F2 L4 | Dengan benda tertutup: **4 ambil 3; 5 ambil 2; 3 ambil 2; 5 ambil 4**. Kunci **1; 3; 1; 1**. |
| F2 L5 | **2 + 5 = ...; 4 + 4 = ...; 6 + 3 = ...; 7 + 3 = ...; 1 + 6 = ...**. Kunci **7; 8; 9; 10; 7**. |
| F2 L6 | **10 − 3 = ...; 9 − 6 = ...; 8 − 2 = ...; 7 − 5 = ...; 6 − 1 = ...**. Kunci **7; 3; 6; 2; 5**. |
| F2 L7 | **9 + 4 = ...; 8 + 7 = ...; 6 + 5 = ...; 7 + 9 = ...; 8 + 9 = ...**. Kunci **13; 15; 11; 16; 17**. Semua butir melewati 10. |
| F2 L8 | **11 − 3 = ...; 13 − 6 = ...; 17 − 8 = ...; 15 − 7 = ...; 12 − 5 = ...**. Kunci **8; 7; 9; 8; 7**. Semua butir melewati 10. |'),
  ('F', 3, 'Catatan Risiko', '- F2 L1–L4 dengan benda tertutup memperjelas batas F2 dari E2, tetapi kelayakan untuk anak L1–L2 perlu diamati langsung karena beban ingatan dan kontrol impuls lebih tinggi daripada menghitung benda terlihat.
- F1 L2 memakai satu butir persegi diputar. Ini baik untuk mencegah pengenalan bentuk hanya dari orientasi khas, tetapi tingkat kesulitannya untuk anak L2 perlu dikalibrasi. **Cadangan F1 L2 tidak memuat persegi diputar**, sehingga paket cadangan sedikit lebih mudah daripada paket utama.
- F1 L1 kini memakai ambang **2 dari 2**. Bukti menjadi lebih kuat, tetapi satu gangguan pada salah satu set langsung menggagalkan indikator bila butir tetap sah.
- F1 L8 bergantung pada konsistensi ukuran satuan dan panjang target. Guru perlu menyiapkan target dengan ukuran aktual yang diperiksa sebelum asesmen.
- F1 L7–L8 berpotensi melewati sasaran satu menit bila penataan satuan lambat; waktu penyiapan dan waktu interaksi perlu dicatat terpisah.
- F2 L5–L6 tetap dapat dipengaruhi pemahaman simbol `+`, `−`, dan `=`, tetapi itu sejalan dengan milestone representasi simbolik. Cadangan F2 L6 memuat satu butir yang sama dengan paket utama (**10 − 3**).
- F2 L7–L8 tidak menyediakan benda hitung; kelulusan dapat dicapai dengan strategi jari, hitung lanjut, fakta hafal, atau strategi mental lain. Strategi tidak dibedakan pada indikator ini.'),
  ('EK', 1, 'Ketentuan Bersama', '- English dan Karakter dicatat dan dinilai **Lulus/Belum**, tetapi **tidak menentukan perpindahan indikator akademik, kenaikan level, atau penentuan level awal diagnostik**.
- Satu paket penilaian dipakai. Bahan cadangan hanya pengganti prapilih, bukan kesempatan tambahan setelah gagal.

### Ketentuan English (amendemen English per tema)

- English memakai **pola/cara uji tetap per level**. Kosakata L2, L3, L5, L6, dan L8 diambil dari kosakata English tema.
- Semua kosakata English satu tema dianggap dikenalkan pada setiap pertemuan tema itu. Kosakata tema tersebut layak uji bagi anak yang hadir pada sedikitnya **tiga pertemuan dalam tema itu**, termasuk kosakata tema sebelumnya yang telah memenuhi syarat.
- Pada diagnostik anak baru, English tidak diuji dan dicatat **belum dinilai**.
- Untuk kelas berjalan, guru menyusun butir secara mekanis dari **daftar layak uji**. Utamakan kosakata tema berjalan; bila belum cukup, gunakan kosakata tema sebelumnya yang sudah memenuhi paparan.
- Bila jumlah kosakata layak uji belum cukup untuk level tersebut, indikator English belum dinilai.
- L5 hanya memakai kata benda English yang diberi tanda wajar diminta pada daftar tema.
- L6 hanya memakai empat frasa tindakan tema yang sudah layak uji; daftar frasa tema harus memuat kontras kata kerja pada kata benda yang sama.
- Tidak memakai phonics bahasa Inggris, nama huruf bahasa Inggris, pembunyian huruf bahasa Inggris, kartu, lembar kerja, bahan cetak, lagu/video, atau gambar representasional. Tulisan dibuat guru saat itu sebagai kata/frasa/kalimat utuh.
- Pelafalan anak dengan logat Indonesia diterima selama kata/frasa sasaran masih dapat dikenali. Jawaban Indonesia belum mendapat poin.
- Semua pilihan benda tetap tersedia sampai butir selesai. Guru tidak menghilangkan pilihan yang sudah dipakai, tidak melatih urutan butir, dan tidak memberi tahu pola kunci.

### Ketentuan Karakter

- Karakter menilai perilaku teramati dalam konteks bimbel, bukan sifat umum, keimanan, hafalan panjang, praktik keluarga, atau kepatuhan akademik A–F.
- Situasi Karakter yang tidak muncul secara wajar, anak belum bersedia, atau pelaksanaan terputus bukan bukti **Belum**; catat sebagai asesmen belum terlaksana dan ambil sampel ulang pada kesempatan wajar.
- Guru tidak mempermalukan anak, tidak menuduh, tidak menjebak, tidak memberi hadiah/hukuman atas isi jawaban, dan tidak membuat tugas yang sengaja tidak mungkin selesai.'),
  ('EK', 2, 'Bahan Cadangan dan Aturan Penerapan', '- Bahan cadangan dipilih sebelum asesmen sebagai pengganti paket utama. Tidak dipakai sebagai paket kedua otomatis setelah anak gagal.
- Untuk English, tidak ada paket cadangan tetap per level. Bila benda tidak tersedia, rusak, bertulisan, atau tidak aman, guru melewati kata/frasa itu dan mengambil kata/frasa layak uji berikutnya dari daftar tema. Pergantian dilakukan **sebelum** uji dimulai, bukan setelah anak salah.
- Untuk Karakter, cadangan berupa konteks setara yang wajar. Bila konteks tidak muncul, hasilnya **belum terlaksana**, bukan **Belum**.

| Sasaran | Bahan cadangan dan penerapan |
|---|---|
| Karakter L1 | Jika salam awal terlewat, amati salam penutupan. Salam umum tetap belum memenuhi. |
| Karakter L2 | Jika pembukaan sudah lewat, gunakan awal kegiatan berikutnya pada sesi yang sama. Jangan meminta hafalan doa panjang. |
| Karakter L3 | Kesempatan cadangan dapat berupa guru menyerahkan penghapus dan membantu membuka wadah. Tetap dua kesempatan wajar bila tersedia; jangan memberi petunjuk “ucapkan terima kasih.” |
| Karakter L4 | Main peran cadangan: benda peran tidak sengaja menyenggol balok teman. Anak diminta menyebut apa yang sebaiknya dikatakan tokoh. |
| Karakter L5 | Simulasi giliran cadangan memakai dua pensil dan dua wadah. Struktur tetap tiga kesempatan menunggu giliran. |
| Karakter L6 | Alat cadangan dapat berupa balok atau buku. Tempat penyimpanan harus terlihat sejak awal kegiatan. |
| Karakter L7 | Tugas cadangan: anak memasukkan tiga benda ke wadah. Tanya pertama ketika baru satu benda masuk, tanya kedua setelah tiga benda masuk. Kunci **belum; sudah**. |
| Karakter L8 | Rutinitas cadangan memakai alat berbeda, tetapi tetap tiga bagian: ambil alat, lakukan tugas pendek, kembalikan alat. Untuk anak baru, boleh dicatat belum terlaksana. |'),
  ('EK', 3, 'Catatan Risiko', '- English L1 kini mewajibkan pembedaan hello/goodbye dengan ucapan; ini menutup celah lambaian, tetapi mungkin lebih berat untuk anak L1 yang pemahamannya muncul lewat isyarat sosial.
- English L8 memakai dua referen per kata benda (warna target dan pengecoh); jumlah benda dapat menambah beban visual dan waktu penataan. Penandaan kata wajar diminta (L5) masih bergantung pada konteks main/alat kelas.
- English kini bergantung pada kehadiran dalam tema; paparan aktual anak pada kata tertentu bisa tidak merata. Pada diagnostik anak baru, English belum dinilai.
- Karakter L3 memakai ambang **1 dari 2**, sehingga lebih toleran terhadap lupa sesaat; dipilih karena Karakter tidak menentukan level dan bertujuan menangkap kebiasaan.
- Karakter L7 lebih mekanis dengan dua keadaan, tetapi masih mengukur jawaban pada skenario terstruktur, bukan sifat jujur secara umum.
- Karakter L6 dan L8 bergantung pada rutinitas kelas; pada diagnostik anak baru, asesmen dapat belum terlaksana atau hasil Belum wajar.'),
  ('TEMA', 1, 'Catatan Umum Tema', '- Tema adalah konteks bersama kelas multi-level. Tema memberi cerita/topik dan benda nyata yang sama, tetapi tidak menentukan indikator anak.
- Urutan tema mengikuti nomor pertemuan 1–192, bukan kalender. Tema tidak diselaraskan dengan musim, Ramadan, atau hari besar tertentu.
- Tema tidak mengubah bahan tes Alur A–F maupun Karakter. Saat menguji indikator akademik atau Karakter, guru tetap memakai dokumen indikator yang terkunci.
- Kata tunggal umum boleh dipakai dalam tema, lisan maupun tulisan, walaupun kebetulan muncul dalam paket tes.
- Yang dilarang adalah melatih **paket utuh**: menulis ulang kalimat tes, daftar kata dalam susunan paket, pasangan bilangan, urutan butir, atau susunan kunci paket utama maupun cadangan.
- Hanya 12 kata terlindungi dari tulisan latihan tema: kosakata inti C2 L3 **buku, bola, susu, mata, kaki, sapi** dan label C2 L2 **lap, air, roti, pot, apel, pena**. Kata-kata itu boleh diucapkan dan bendanya boleh dipakai, tetapi tidak dijadikan tulisan latihan tema.
- Kosakata English tema dikenalkan melalui kegiatan tema. Yang dilarang adalah melatih urutan butir, posisi kunci, atau format tes English.
- Benda umum yang kebetulan sama dengan bahan tes boleh dipakai sebagai benda konteks selama tidak dipakai untuk melatih paket tes utuh.');

insert into public.k8_themes(number, name, first_meeting, last_meeting, description, objects, vocabulary, character, illustration) values
  (1, 'Rumah dan Kebiasaan Harian', 1, 24, 'Tema ini memakai benda dan rutinitas rumah sebagai konteks bersama untuk berbicara, menghitung, mengelompokkan, mengukur, menulis, dan membangun kebiasaan rapi.', 'kain serbet polos, sapu kecil, wadah plastik, kotak penyimpanan, sandal bersih, gantungan baju, bantal kecil, botol kosong polos, tutup botol, cangkir polos.', 'rumah, ruang, bersih, rapi, simpan, ambil, letak, pagi, sore, kebiasaan, tempat, bantu.', 'salam saat datang, doa sebelum belajar, mengucapkan terima kasih saat menerima alat, menunggu giliran memakai benda, dan merapikan alat setelah kegiatan.', 'Anak L1 dapat mengelompokkan benda rumah berdasarkan warna; anak L4 dapat menceritakan dua tindakan yang dilihat, misalnya mengambil kain lalu menaruhnya; anak L8 dapat menulis satu kalimat sederhana tentang rutinitas merapikan alat.'),
  (2, 'Pasar dan Warung', 25, 48, 'Tema ini memakai suasana pasar kecil dan warung sebagai konteks benda nyata yang mudah dihitung, dibandingkan, dikelompokkan, dan diceritakan.', 'wortel, tomat, mentimun, jeruk, pisang, salak, keranjang kecil, kantong kain polos, wadah bening polos, karet gelang, tutup wadah, uang mainan polos tanpa angka.', 'pasar, warung, sayur, buah, keranjang, pilih, banyak, sedikit, panjang, pendek, kelompok, jual.', 'antre saat memilih benda, berterima kasih setelah menerima benda, jujur saat menyatakan tugas sudah/belum selesai, dan merapikan dagangan main.', 'Anak L1 dapat menyebut nama benda pasar; anak L4 dapat membagi lima benda dagangan menjadi dua kelompok; anak L8 dapat memakai bilangan 11–20 yang ditulis guru dalam konteks jumlah benda tanpa memakai paket tes.'),
  (3, 'Kebun dan Tanaman', 49, 72, 'Tema ini menghadirkan tanaman, biji, dan alat kebun sederhana sebagai konteks konkret untuk mengamati ciri benda, pola, urutan, ukuran, dan perubahan.', 'daun, ranting, biji kacang hijau, kapas tanam, batu kecil, tali rafia, sekop plastik, penyiram kecil kosong, nampan, wadah tanah kering tertutup.', 'kebun, tanaman, daun, biji, tunas, tumbuh, rawat, kering, basah, urut, ukur, siram.', 'meminta izin memakai alat, menunggu giliran menyentuh bahan, berterima kasih saat dibantu, menjaga kebersihan, dan mengembalikan alat ke tempatnya.', 'Anak L1 dapat menghitung benda 1–3 dari kebun; anak L4 dapat melanjutkan pola tiga unsur dengan daun, batu, dan ranting; anak L8 dapat memperkirakan panjang tali dengan satuan tidak baku.'),
  (4, 'Dapur dan Makanan Sehat', 73, 96, 'Tema ini memakai alat makan dan bahan makanan nyata sebagai konteks untuk bahasa, bilangan, kategori, ukuran, dan adab sebelum/sesudah kegiatan.', 'piring plastik, mangkuk plastik, sendok, nampan, serbet polos, wortel, kentang, jagung, buncis, botol kosong polos, spons bersih.', 'dapur, sehat, piring, mangkuk, nampan, sayur, rasa, lembut, keras, hangat, dingin, siapkan.', 'doa sebelum belajar, berbagi alat, menunggu giliran, meminta maaf dalam main peran ringan, dan merapikan meja.', 'Anak L1 dapat mengikuti instruksi menyentuh benda; anak L4 dapat menceritakan kejadian dua kalimat yang didengar; anak L8 dapat memahami hubungan sebab-akibat dari dua kalimat baru yang ditulis guru sesuai indikator, bukan paket tes.'),
  (5, 'Kendaraan dan Jalan', 97, 120, 'Tema ini memakai kendaraan mainan polos dan jalur sederhana untuk konteks urutan, posisi, sebab-akibat, bilangan, pola, dan cerita.', 'mobil mainan polos, truk mainan polos, tali sebagai jalan, balok sebagai jembatan, tutup botol sebagai roda, kain sebagai jalan, kotak sebagai garasi, stik polos, helm mainan polos.', 'jalan, kendaraan, maju, berhenti, belok, dekat, jauh, jembatan, garasi, cepat, pelan, perjalanan.', 'menunggu giliran menjalankan kendaraan, meminta maaf dalam main peran tabrakan kecil, jujur saat tugas selesai/belum, dan merapikan jalur.', 'Anak L1 dapat menunjuk kendaraan yang disebut; anak L4 dapat menentukan bilangan sebelum/sesudah dalam konteks nomor yang ditulis guru; anak L8 dapat menceritakan cerita pendek tentang kendaraan yang terhalang lalu berhasil sampai.'),
  (6, 'Masjid dan Adab Harian', 121, 144, 'Tema ini memakai benda dan rutinitas adab harian yang dekat dengan identitas bimbel Islami, tanpa menilai keimanan atau praktik keluarga.', 'sajadah kecil polos, peci, sarung kecil, mukena anak, sandal bersih, kain penutup, kotak polos, botol kosong polos, wadah alat.', 'salam, doa, bersih, rapi, giliran, bantu, maaf, terima kasih, simpan, hormat, tenang, bersama.', 'salam Islami, doa pendek sebelum belajar, menunggu giliran, mengucapkan terima kasih, merapikan alat, dan main peran meminta maaf.', 'Anak L1 dapat mengelompokkan benda berdasarkan satu atribut; anak L4 dapat memisahkan kata lisan menjadi suku kata sesuai bahan indikator; anak L8 dapat menjalankan rutinitas kelas pendek yang sudah dikenal.'),
  (7, 'Alam dan Cuaca', 145, 168, 'Tema ini memakai benda alam sekitar dan kondisi cuaca sederhana sebagai konteks untuk mengamati, membandingkan, mengurutkan, mengukur, dan memahami sebab-akibat.', 'payung kecil polos, kain kering, kain lembap, kipas tangan polos, daun kering, batu kecil, ranting, wadah bening kosong, ember kecil polos, tali, penjepit, kapas, nampan.', 'alam, cuaca, panas, teduh, hujan, kering, lembap, angin, bergerak, jatuh, ringan, berat.', 'membantu mengambil benda yang jatuh, berterima kasih, menunggu giliran memakai kipas, menyatakan tugas sudah/belum selesai, dan merapikan bahan alam.', 'Anak L1 dapat menyebut benda; anak L4 dapat menemukan informasi tersurat dari dua kalimat lisan; anak L8 dapat menentukan sebab-akibat dari kalimat baru yang dibaca sendiri.'),
  (8, 'Tubuh Sehat dan Gerak', 169, 192, 'Tema ini memakai alat kebersihan diri, gerak sederhana, dan rutinitas sehat sebagai konteks konkret untuk bahasa, urutan, ukuran, dan kemandirian.', 'sikat gigi baru tertutup, handuk kecil, sisir, sabun kemasan polos atau ditutup, botol kosong polos, pita gerak, bola kecil polos, matras kecil, wadah alat, kain penanda tempat.', 'sehat, gerak, lompat, duduk, berdiri, cuci, bersih, istirahat, kuat, lelah, rapi, rutinitas.', 'menjalankan rutinitas pendek, merapikan alat, menunggu giliran gerak, meminta maaf dalam main peran ringan, dan berterima kasih setelah dibantu.', 'Anak L1 dapat melakukan satu instruksi lisan; anak L4 dapat membaca kata sederhana yang dibuat guru dan bukan paket tes; anak L8 dapat menulis satu kalimat dari gagasan sendiri tentang rutinitas sehat.');

